insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('f6000000-0000-0000-0000-000000000001', 'mrcp1', '8263d166-b8f1-41d2-abb0-085b8b1ed5a6',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('f6000000-0000-0000-0000-000000000001', 'A', 'Superior vena cava obstruction', true, 'Correct. Facial and neck swelling, distended neck veins, breathlessness worse lying flat, and dilated collateral chest wall veins in a patient with known lung cancer (a common cause) are characteristic of superior vena cava obstruction, caused by extrinsic compression or direct tumour invasion of the SVC, requiring urgent imaging and treatment.', 1),
('f6000000-0000-0000-0000-000000000001', 'B', 'Right heart failure', false, 'Ruled out because although right heart failure also causes venous congestion, the specific combination of facial swelling and dilated collateral chest wall veins in a patient with known thoracic malignancy is much more characteristic of SVC obstruction.', 2),
('f6000000-0000-0000-0000-000000000001', 'C', 'Pericardial tamponade', false, 'Ruled out because tamponade causes hypotension and pulsus paradoxus from impaired cardiac filling, not primarily this facial/neck swelling and collateral vein pattern, though both can occur in malignancy and should be considered.', 3),
('f6000000-0000-0000-0000-000000000001', 'D', 'Simple anaphylaxis', false, 'Ruled out because anaphylaxis causes acute facial/airway swelling with urticaria and hypotension, not this gradual pattern with dilated collateral veins in the context of known malignancy.', 4),
('f6000000-0000-0000-0000-000000000001', 'E', 'Nephrotic syndrome', false, 'Ruled out because nephrotic syndrome causes generalised oedema from hypoalbuminaemia, not this specific pattern of facial/neck swelling with dilated collateral chest wall veins characteristic of venous obstruction.', 5),
('f6000000-0000-0000-0000-000000000002', 'A', 'Routine outpatient MRI within the next two weeks', false, 'Ruled out because metastatic spinal cord compression is a time-critical emergency where delay significantly worsens neurological outcome; imaging and treatment must be arranged urgently, not on a routine outpatient basis.', 1),
('f6000000-0000-0000-0000-000000000002', 'B', 'Simple analgesia only, with no further immediate action', false, 'Ruled out because this represents a neurological emergency requiring urgent specific treatment (steroids, imaging, definitive intervention) to preserve neurological function, not analgesia alone.', 2),
('f6000000-0000-0000-0000-000000000002', 'C', 'Urgent MRI whole spine and high-dose dexamethasone', true, 'Correct. New bilateral leg weakness, a sensory level, and urinary retention in a patient with known malignancy is characteristic of metastatic spinal cord compression, a time-critical oncological emergency; urgent MRI whole spine to confirm the diagnosis and level, alongside immediate high-dose dexamethasone to reduce cord oedema, should be arranged without delay, with urgent oncology/spinal surgery input regarding further treatment (radiotherapy or surgical decompression).', 3),
('f6000000-0000-0000-0000-000000000002', 'D', 'Physiotherapy referral as the primary immediate intervention', false, 'Ruled out because although physiotherapy is relevant to rehabilitation, the immediate priority is urgent diagnosis and treatment to prevent further, potentially permanent neurological damage.', 4),
('f6000000-0000-0000-0000-000000000002', 'E', 'Discharge home with outpatient follow-up', false, 'Ruled out because this represents an emergency requiring immediate inpatient assessment and treatment, not discharge with delayed follow-up.', 5),
('f6000000-0000-0000-0000-000000000003', 'A', 'Oral antibiotics with outpatient follow-up', false, 'Ruled out because neutropenic sepsis is a medical emergency requiring immediate inpatient IV antibiotic treatment, not oral antibiotics managed as an outpatient.', 1),
('f6000000-0000-0000-0000-000000000003', 'B', 'Wait for blood culture results before starting any antibiotics', false, 'Ruled out because delaying antibiotics while awaiting culture results in neutropenic sepsis significantly increases mortality risk; empirical treatment must start immediately on clinical suspicion.', 2),
('f6000000-0000-0000-0000-000000000003', 'C', 'Granulocyte colony-stimulating factor (G-CSF) alone, without antibiotics', false, 'Ruled out because although G-CSF may be used as an adjunct in some cases, it does not treat the underlying infection; immediate antibiotics remain the essential first-line emergency treatment.', 3),
('f6000000-0000-0000-0000-000000000003', 'D', 'Antipyretics alone, with reassessment in 24 hours', false, 'Ruled out because this represents a life-threatening emergency requiring immediate antibiotic treatment, not symptomatic treatment with delayed reassessment.', 4),
('f6000000-0000-0000-0000-000000000003', 'E', 'Immediate empirical broad-spectrum IV antibiotics, without waiting for investigation results', true, 'Correct. Fever in a patient with chemotherapy-induced neutropenia (neutropenic sepsis) is a medical emergency; empirical broad-spectrum IV antibiotics (per local protocol, typically within one hour of presentation) should be given immediately, alongside cultures and other investigations, without waiting for results, given the high risk of rapid deterioration and mortality if treatment is delayed.', 5),
('f6000000-0000-0000-0000-000000000004', 'A', 'Oral calcium supplementation', false, $x$Ruled out because giving additional calcium would dangerously worsen this patient's already severe hypercalcaemia.$x$, 1),
('f6000000-0000-0000-0000-000000000004', 'B', 'Loop diuretic as the first-line treatment before fluids', false, 'Ruled out because loop diuretics should not be given to a volume-depleted patient before adequate rehydration, as this can worsen renal function and hypercalcaemia.', 2),
('f6000000-0000-0000-0000-000000000004', 'C', 'Fluid restriction to avoid overload', false, 'Ruled out because fluid restriction would worsen the hypercalcaemia; these patients are typically significantly volume-depleted, and aggressive rehydration (not restriction) is the priority.', 3),
('f6000000-0000-0000-0000-000000000004', 'D', 'IV 0.9% saline rehydration followed by an IV bisphosphonate', true, 'Correct. Severe symptomatic hypercalcaemia of malignancy is managed with aggressive IV isotonic saline rehydration first (correcting volume depletion and promoting renal calcium excretion), followed by an IV bisphosphonate (e.g. zoledronic acid) for more sustained calcium lowering via osteoclast inhibition.', 4),
('f6000000-0000-0000-0000-000000000004', 'E', 'Oral bisphosphonate alone as first-line treatment', false, 'Ruled out because oral bisphosphonates have poor bioavailability and are inappropriate for severe, symptomatic hypercalcaemia, which requires IV rehydration and an IV bisphosphonate.', 5),
('f6000000-0000-0000-0000-000000000005', 'A', 'No specific prophylaxis is needed; treatment can begin as normal', false, 'Ruled out because this patient has specific high-risk features (bulky, rapidly proliferating tumour) for tumour lysis syndrome, making proactive prophylaxis clinically important rather than proceeding without any preventive measures.', 1),
('f6000000-0000-0000-0000-000000000005', 'B', 'Pre-treatment hydration and prophylactic urate-lowering therapy (e.g. allopurinol or rasburicase)', true, 'Correct. In patients at high risk of tumour lysis syndrome (bulky, rapidly proliferating tumours such as high-grade lymphoma), prophylactic measures -- adequate IV hydration and urate-lowering therapy (allopurinol, or rasburicase for higher-risk patients) started before chemotherapy -- reduce the risk of this life-threatening metabolic complication.', 2),
('f6000000-0000-0000-0000-000000000005', 'C', 'Fluid restriction before starting chemotherapy', false, 'Ruled out because adequate hydration (not restriction) is a key preventive measure for tumour lysis syndrome, helping maintain renal clearance of released intracellular contents.', 3),
('f6000000-0000-0000-0000-000000000005', 'D', 'Prophylactic dialysis before any chemotherapy is given', false, 'Ruled out because prophylactic dialysis is not standard practice before chemotherapy; hydration and urate-lowering therapy are the standard preventive measures, with dialysis reserved for established, severe tumour lysis syndrome not responding to medical management.', 4),
('f6000000-0000-0000-0000-000000000005', 'E', 'Delaying chemotherapy indefinitely due to tumour lysis syndrome risk', false, 'Ruled out because appropriate prophylactic measures allow chemotherapy to proceed safely in most cases; indefinite delay is not the appropriate response to this identifiable and manageable risk.', 5),
('f6000000-0000-0000-0000-000000000006', 'A', 'Simple viral hepatitis unrelated to her malignancy', false, 'Ruled out because the clear context of extensive known hepatic metastases provides a much more likely explanation for her acute liver failure than a coincidental new viral hepatitis infection.', 1),
('f6000000-0000-0000-0000-000000000006', 'B', 'Paracetamol overdose', false, 'Ruled out because there is no history of paracetamol overdose given, and the clinical context (known extensive hepatic metastases) provides a clear alternative explanation for her liver failure.', 2),
('f6000000-0000-0000-0000-000000000006', 'C', 'Alcoholic liver disease', false, 'Ruled out because there is no alcohol history given, and the known extensive hepatic metastatic disease is the clear and directly relevant explanation for her presentation.', 3),
('f6000000-0000-0000-0000-000000000006', 'D', 'Gallstone disease with cholangitis', false, 'Ruled out because there is no mention of biliary obstruction or infective features, and the known extensive hepatic metastatic burden is the more likely and directly relevant cause of her hepatic failure.', 4),
('f6000000-0000-0000-0000-000000000006', 'E', 'Acute liver failure secondary to extensive hepatic metastatic replacement', true, 'Correct. Confusion (hepatic encephalopathy), jaundice and coagulopathy in a patient with extensive hepatic metastases reflects acute liver failure from malignant replacement of functional liver tissue, an oncological emergency with a generally poor prognosis, requiring urgent assessment and supportive care alongside discussion of appropriate goals of care.', 5),
('f6000000-0000-0000-0000-000000000007', 'A', 'Multidisciplinary assessment for pain control, radiotherapy and/or surgical stabilisation as appropriate, with ongoing monitoring for cord compression', true, 'Correct. A pathological vertebral fracture from bone metastases, without current cord compression, requires multidisciplinary assessment (oncology, spinal surgery, palliative care as relevant) to determine the best combination of pain control, radiotherapy (to treat the underlying metastatic disease and reduce further fracture/collapse risk), and consideration of surgical stabilisation if indicated, alongside ongoing vigilance for any signs of evolving cord compression.', 1),
('f6000000-0000-0000-0000-000000000007', 'B', 'No specific treatment needed, as there is no current cord compression', false, 'Ruled out because although cord compression is absent now, active management (pain control, radiotherapy, stabilisation consideration) is still needed to address the pathological fracture and reduce the risk of further complications, including potential future cord compression.', 2),
('f6000000-0000-0000-0000-000000000007', 'C', 'Immediate spinal fusion surgery regardless of clinical findings', false, 'Ruled out because surgical decision-making should be individualised based on multidisciplinary assessment, not applied uniformly regardless of the specific clinical and radiological findings and patient factors.', 3),
('f6000000-0000-0000-0000-000000000007', 'D', 'High-dose steroids as the sole ongoing treatment, with no further intervention', false, 'Ruled out because although steroids have a role in cord compression, ongoing management of a pathological fracture without current cord compression involves a broader multidisciplinary approach (pain control, radiotherapy, stabilisation consideration), not steroids alone.', 4),
('f6000000-0000-0000-0000-000000000007', 'E', 'Discharge with no follow-up, as there is no immediate emergency', false, 'Ruled out because ongoing follow-up and monitoring is important given the risk of future complications (further fracture, evolving cord compression) and the need for coordinated multidisciplinary management.', 5),
('f6000000-0000-0000-0000-000000000008', 'A', 'Aspirin alone as definitive treatment', false, 'Ruled out because aspirin alone is not adequate treatment for a confirmed pulmonary embolism; therapeutic anticoagulation is required.', 1),
('f6000000-0000-0000-0000-000000000008', 'B', 'Observation only, with no anticoagulation', false, 'Ruled out because a confirmed pulmonary embolism requires active anticoagulation treatment to prevent extension and further embolic events, not simple observation.', 2),
('f6000000-0000-0000-0000-000000000008', 'C', 'Anticoagulation, typically with a low molecular weight heparin or, depending on individual factors, a direct oral anticoagulant', true, 'Correct. Confirmed pulmonary embolism in a cancer patient requires prompt anticoagulation; low molecular weight heparin has traditionally been preferred in cancer-associated thrombosis given its established efficacy and safety profile in this population, though direct oral anticoagulants are increasingly used in appropriately selected patients, guided by individual bleeding risk and cancer type.', 3),
('f6000000-0000-0000-0000-000000000008', 'D', 'Immediate IVC filter insertion as first-line treatment instead of anticoagulation', false, 'Ruled out because IVC filters are reserved for specific situations (e.g. absolute contraindication to anticoagulation, or recurrent PE despite adequate anticoagulation), not as first-line treatment in place of anticoagulation for a standard confirmed PE.', 4),
('f6000000-0000-0000-0000-000000000008', 'E', 'Thrombolysis for all patients with confirmed pulmonary embolism, regardless of severity', false, 'Ruled out because thrombolysis is reserved for massive PE with haemodynamic compromise, not used routinely for all PE regardless of severity, given its significant bleeding risk.', 5),
('f6000000-0000-0000-0000-000000000009', 'A', 'Rapid correction with hypertonic saline regardless of the rate of rise', false, 'Ruled out because although hypertonic saline may be used cautiously in severe, symptomatic hyponatraemia under close monitoring, correction must be carefully controlled and gradual, not rapid, given the significant risk of osmotic demyelination syndrome from overly fast correction.', 1),
('f6000000-0000-0000-0000-000000000009', 'B', 'IV 0.9% saline as the primary treatment', false, 'Ruled out because in SIADH, standard isotonic saline is often ineffective (and can even worsen hyponatraemia in some cases) since the kidneys continue to concentrate urine; fluid restriction is the mainstay approach instead.', 2),
('f6000000-0000-0000-0000-000000000009', 'C', $x$Fluid loading to dilute and 'flush out' the excess sodium concern$x$, false, 'Ruled out because increasing fluid intake would worsen, not improve, hyponatraemia in SIADH, where free water excretion is already impaired.', 3),
('f6000000-0000-0000-0000-000000000009', 'D', 'Fluid restriction, with cautious correction and close monitoring given the severity', true, 'Correct. Severe, symptomatic hyponatraemia from SIADH (a paraneoplastic complication of small cell lung cancer) is managed with fluid restriction as the mainstay of initial treatment, with careful, gradual correction (not overly rapid) to avoid osmotic demyelination syndrome, alongside treatment of the underlying malignancy where possible.', 4),
('f6000000-0000-0000-0000-000000000009', 'E', 'No treatment needed, as this is an expected finding in lung cancer', false, 'Ruled out because severe, symptomatic hyponatraemia requires active management given the risk of significant morbidity (seizures, reduced consciousness) if left untreated, rather than being disregarded as an expected, inconsequential finding.', 5),
('f6000000-0000-0000-0000-000000000010', 'A', 'Only if the temperature exceeds 40C', false, 'Ruled out because waiting for such a high threshold would dangerously delay presentation and treatment of neutropenic sepsis; a much lower threshold (around 38C) is used specifically because of the risk of rapid deterioration.', 1),
('f6000000-0000-0000-0000-000000000010', 'B', 'Any fever (typically defined as a temperature above 38C)', true, 'Correct. Patients receiving chemotherapy should be advised to seek immediate medical assessment for any fever (commonly defined as a single temperature above 38C, or above 37.5C sustained), given the risk of neutropenic sepsis, which can progress rapidly and requires urgent empirical antibiotic treatment.', 2),
('f6000000-0000-0000-0000-000000000010', 'C', 'Only if accompanied by a rash', false, 'Ruled out because neutropenic sepsis can present with fever alone, without a rash, and the presence or absence of a rash should not determine whether urgent assessment is sought.', 3),
('f6000000-0000-0000-0000-000000000010', 'D', 'Only if symptoms persist for more than 48 hours', false, 'Ruled out because delaying presentation for 48 hours in neutropenic sepsis significantly increases the risk of serious deterioration; immediate assessment for any fever is required, not delayed presentation.', 4),
('f6000000-0000-0000-0000-000000000010', 'E', 'Fever is not a specific concern requiring urgent action in chemotherapy patients', false, 'Ruled out because fever is specifically the key symptom prompting urgent assessment for neutropenic sepsis in this population, given the significant associated risks if not promptly treated.', 5),
('f6000000-0000-0000-0000-000000000011', 'A', 'Simple constipation unrelated to her malignancy', false, 'Ruled out because the severity of presentation (sudden, severe pain, distension with dilated loops on imaging) in the context of known ovarian cancer with peritoneal spread potential points to malignant obstruction rather than simple constipation.', 1),
('f6000000-0000-0000-0000-000000000011', 'B', 'Malignant bowel obstruction', true, 'Correct. Sudden severe abdominal pain, distension and absolute constipation with dilated bowel loops on imaging, in a patient with known ovarian cancer (a common cause of peritoneal carcinomatosis and malignant bowel obstruction), is characteristic of malignant bowel obstruction, requiring urgent surgical/oncological assessment to determine the most appropriate management approach (which may range from surgical intervention to medical symptom management depending on individual circumstances).', 2),
('f6000000-0000-0000-0000-000000000011', 'C', 'Acute pancreatitis', false, 'Ruled out because although pancreatitis causes abdominal pain, it does not typically cause this specific pattern of absolute constipation with dilated bowel loops on imaging characteristic of mechanical or malignant obstruction.', 3),
('f6000000-0000-0000-0000-000000000011', 'D', 'Diverticulitis', false, 'Ruled out because although diverticulitis can cause obstruction, the strong context of known ovarian cancer (a classic cause of malignant bowel obstruction via peritoneal spread) makes this the more likely primary diagnosis to consider first.', 4),
('f6000000-0000-0000-0000-000000000011', 'E', 'Irritable bowel syndrome', false, 'Ruled out because IBS is a chronic functional disorder, not this acute, severe presentation with radiological evidence of bowel obstruction.', 5),
('f6000000-0000-0000-0000-000000000012', 'A', 'Hyperviscosity syndrome (leukostasis)', true, 'Correct. Confusion, visual disturbance and breathlessness in a patient with an extremely elevated white cell count (leukostasis) reflects hyperviscosity syndrome, where the markedly increased number of circulating blast cells impairs blood flow through small vessels, particularly affecting the brain and lungs; this is a medical emergency requiring urgent cytoreduction (e.g. leukapheresis, hydroxycarbamide, and prompt initiation of definitive chemotherapy).', 1),
('f6000000-0000-0000-0000-000000000012', 'B', 'Simple anaemia-related symptoms', false, 'Ruled out because these specific symptoms (confusion, visual disturbance, breathlessness) in the context of an extremely elevated white cell count reflect hyperviscosity/leukostasis, not simply anaemia, which would present differently.', 2),
('f6000000-0000-0000-0000-000000000012', 'C', 'Anxiety related to his new leukaemia diagnosis', false, 'Ruled out because these are objective, serious clinical symptoms with a clear underlying physiological mechanism (leukostasis from extreme leucocytosis), not simply anxiety.', 3),
('f6000000-0000-0000-0000-000000000012', 'D', 'Simple dehydration', false, 'Ruled out because although dehydration can contribute to some degree of hyperviscosity, the specific extreme leucocytosis and symptom pattern described point specifically to leukostasis as the primary mechanism.', 4),
('f6000000-0000-0000-0000-000000000012', 'E', 'Normal expected symptoms of acute leukaemia requiring no specific urgent action', false, 'Ruled out because hyperviscosity syndrome from extreme leucocytosis is a specific medical emergency requiring urgent treatment, not a symptom pattern to be regarded as routine or requiring no active intervention.', 5),
('f6000000-0000-0000-0000-000000000013', 'A', 'Immediate lumbar puncture to relieve pressure', false, $x$Ruled out because lumbar puncture is contraindicated in the presence of significant midline shift and raised intracranial pressure from a mass lesion, given the significant risk of precipitating brain herniation ('coning').$x$, 1),
('f6000000-0000-0000-0000-000000000013', 'B', 'Simple analgesia only, with no other intervention', false, 'Ruled out because this represents a neurological emergency requiring specific treatment (dexamethasone) to reduce oedema and prevent further neurological deterioration, not analgesia alone.', 2),
('f6000000-0000-0000-0000-000000000013', 'C', 'Discharge home with outpatient oncology follow-up', false, 'Ruled out because this represents an acute neurological emergency requiring immediate inpatient assessment and treatment, not outpatient management.', 3),
('f6000000-0000-0000-0000-000000000013', 'D', 'High-dose dexamethasone to reduce peritumoural oedema, alongside urgent oncology/neurosurgical assessment', true, 'Correct. Raised intracranial pressure from oedema surrounding brain metastases, causing new severe headache, vomiting and reduced consciousness, is a neuro-oncological emergency; high-dose dexamethasone rapidly reduces peritumoural oedema and can improve symptoms, given alongside urgent further assessment (further imaging, oncology/neurosurgical input) to guide further definitive management (e.g. radiotherapy, surgical decompression if appropriate).', 4),
('f6000000-0000-0000-0000-000000000013', 'E', 'Immediate whole brain radiotherapy before any other treatment', false, 'Ruled out because although radiotherapy may be part of definitive management, the immediate priority is reducing oedema with dexamethasone and stabilising the patient, with radiotherapy planning following appropriate further assessment, not administered as the very first emergency step.', 5),
('f6000000-0000-0000-0000-000000000014', 'A', 'CA-125, associated with ovarian cancer', false, $x$Ruled out because CA-125 is a marker used for ovarian cancer, not relevant to this male patient's prostate presentation.$x$, 1),
('f6000000-0000-0000-0000-000000000014', 'B', 'CEA, associated with colorectal cancer', false, 'Ruled out because carcinoembryonic antigen is used mainly in colorectal cancer monitoring, not as the primary marker for prostate pathology described here.', 2),
('f6000000-0000-0000-0000-000000000014', 'C', 'AFP, associated with hepatocellular carcinoma', false, 'Ruled out because alpha-fetoprotein is associated with hepatocellular carcinoma and certain germ cell tumours, not the prostate-specific marker relevant to this presentation.', 3),
('f6000000-0000-0000-0000-000000000014', 'D', 'CA 19-9, associated with pancreatic cancer', false, 'Ruled out because CA 19-9 is associated with pancreatic and biliary tract cancers, not the prostate-specific marker relevant here.', 4),
('f6000000-0000-0000-0000-000000000014', 'E', 'Prostate-specific antigen, associated with prostate cancer', true, 'Correct. PSA is the tumour marker used here, produced by prostate epithelial cells; while it can be elevated in benign conditions (BPH, prostatitis), a markedly raised level combined with a hard, irregular prostate on examination raises strong suspicion of prostate cancer, warranting further investigation (e.g. biopsy).', 5),
('f6000000-0000-0000-0000-000000000015', 'A', 'Endometriosis alone', false, 'Ruled out because although endometriosis can mildly raise CA-125, the combination of a complex mass on imaging with markedly (rather than mildly) elevated CA-125 raises greater specific concern for malignancy requiring urgent further investigation.', 1),
('f6000000-0000-0000-0000-000000000015', 'B', 'Simple ovarian cyst', false, 'Ruled out because a simple (rather than complex) cyst with normal or only mildly raised CA-125 would be more reassuring; the combination of a complex mass with markedly elevated CA-125 raises specific concern for malignancy.', 2),
('f6000000-0000-0000-0000-000000000015', 'C', 'Ovarian cancer', true, 'Correct. Non-specific symptoms (bloating, early satiety, pelvic discomfort) combined with a complex ovarian mass on imaging and markedly elevated CA-125 raises significant suspicion of ovarian cancer, prompting further investigation and specialist gynae-oncology referral.', 3),
('f6000000-0000-0000-0000-000000000015', 'D', 'Pelvic inflammatory disease', false, 'Ruled out because PID would typically present with fever and infective features, and would not classically cause this combination of a complex ovarian mass with markedly elevated CA-125.', 4),
('f6000000-0000-0000-0000-000000000015', 'E', 'Normal physiological finding requiring no further action', false, 'Ruled out because this combination of findings (complex mass, markedly elevated CA-125, symptoms) warrants urgent further investigation, not being dismissed as a normal, inconsequential finding.', 5),
('f6000000-0000-0000-0000-000000000016', 'A', 'Epididymo-orchitis', false, 'Ruled out because epididymo-orchitis is an infective/inflammatory condition typically presenting with pain and tenderness, and would not be associated with markedly elevated AFP and beta-hCG, which are specific tumour markers for germ cell tumours.', 1),
('f6000000-0000-0000-0000-000000000016', 'B', 'Testicular germ cell tumour', true, 'Correct. A testicular mass with elevated AFP and/or beta-hCG (tumour markers characteristically raised in germ cell tumours, particularly non-seminomatous types) in a young man is characteristic of testicular cancer; these markers are also used for staging, monitoring treatment response and detecting recurrence.', 2),
('f6000000-0000-0000-0000-000000000016', 'C', 'Hydrocele', false, 'Ruled out because a hydrocele is a benign fluid collection, not associated with elevated tumour markers; the findings described point specifically to a germ cell tumour.', 3),
('f6000000-0000-0000-0000-000000000016', 'D', 'Varicocele', false, 'Ruled out because a varicocele is a benign venous abnormality, not associated with a discrete mass or elevated tumour markers.', 4),
('f6000000-0000-0000-0000-000000000016', 'E', 'Testicular torsion', false, 'Ruled out because torsion presents acutely with severe pain, not this painless mass with elevated tumour markers, which is characteristic of malignancy.', 5),
('f6000000-0000-0000-0000-000000000017', 'A', 'CA-125', false, 'Ruled out because CA-125 is used for ovarian cancer surveillance/monitoring, not hepatocellular carcinoma surveillance in cirrhosis.', 1),
('f6000000-0000-0000-0000-000000000017', 'B', 'PSA', false, 'Ruled out because PSA is specific to prostate tissue and has no role in hepatocellular carcinoma surveillance.', 2),
('f6000000-0000-0000-0000-000000000017', 'C', 'CA 19-9', false, 'Ruled out because CA 19-9 is primarily associated with pancreatic and biliary tract cancers, not the standard marker used for HCC surveillance in cirrhosis.', 3),
('f6000000-0000-0000-0000-000000000017', 'D', 'Alpha-fetoprotein (AFP)', true, 'Correct. AFP is the tumour marker traditionally used alongside 6-monthly ultrasound surveillance for hepatocellular carcinoma in patients with cirrhosis, a population at significantly increased risk; a rising AFP alongside a new liver lesion on imaging raises strong suspicion for HCC, prompting further investigation.', 4),
('f6000000-0000-0000-0000-000000000017', 'E', 'CEA', false, 'Ruled out because CEA is mainly used in colorectal cancer, not as the standard tumour marker for HCC surveillance in cirrhotic patients.', 5),
('f6000000-0000-0000-0000-000000000018', 'A', 'Carcinoembryonic antigen (CEA)', true, 'Correct. CEA is the tumour marker typically used for surveillance monitoring after treatment for colorectal cancer; a rising CEA level during follow-up raises suspicion of disease recurrence, prompting further investigation with imaging.', 1),
('f6000000-0000-0000-0000-000000000018', 'B', 'CA-125', false, 'Ruled out because CA-125 is specific to ovarian cancer monitoring, not the standard marker used for colorectal cancer surveillance.', 2),
('f6000000-0000-0000-0000-000000000018', 'C', 'PSA', false, 'Ruled out because PSA is prostate-specific, with no role in colorectal cancer surveillance.', 3),
('f6000000-0000-0000-0000-000000000018', 'D', 'AFP', false, 'Ruled out because AFP is used for hepatocellular carcinoma and certain germ cell tumours, not standard colorectal cancer surveillance.', 4),
('f6000000-0000-0000-0000-000000000018', 'E', 'Beta-hCG', false, 'Ruled out because beta-hCG is used for germ cell tumours and gestational trophoblastic disease monitoring, not colorectal cancer surveillance.', 5),
('f6000000-0000-0000-0000-000000000019', 'A', 'Preventing breast cancer from ever developing', false, 'Ruled out because screening does not prevent cancer from developing; it aims to detect cancer earlier if and when it does develop, distinguishing screening (early detection) from primary prevention (preventing occurrence).', 1),
('f6000000-0000-0000-0000-000000000019', 'B', 'Diagnosing and treating symptomatic breast lumps more quickly', false, 'Ruled out because population screening specifically targets asymptomatic women; symptomatic presentations are assessed through a separate, urgent referral pathway, not through the routine screening programme.', 2),
('f6000000-0000-0000-0000-000000000019', 'C', 'Replacing the need for any breast awareness or symptom reporting between screening rounds', false, 'Ruled out because screening does not replace the importance of women remaining aware of any new breast changes and reporting them promptly between scheduled screening rounds, given that cancers can develop in the interval between screens.', 3),
('f6000000-0000-0000-0000-000000000019', 'D', 'Providing a definitive diagnosis without any need for further investigation of an abnormal result', false, 'Ruled out because an abnormal screening result requires further diagnostic investigation (e.g. further imaging, biopsy) to confirm or exclude cancer; screening itself is not diagnostic.', 4),
('f6000000-0000-0000-0000-000000000019', 'E', 'Detecting breast cancer at an early, more treatable stage in asymptomatic women, reducing breast cancer mortality', true, 'Correct. Population-based mammographic screening aims to detect breast cancer at an earlier, more treatable stage in asymptomatic women within the target age range, with evidence supporting a reduction in breast cancer-specific mortality at a population level, though it also carries recognised limitations (false positives, overdiagnosis) that are part of the informed decision to participate.', 5),
('f6000000-0000-0000-0000-000000000020', 'A', 'Tumour DNA specifically shed by cancer cells', false, 'Ruled out because although newer stool-based tests exist that detect tumour DNA, the standard FIT specifically detects human haemoglobin, not tumour DNA directly.', 1),
('f6000000-0000-0000-0000-000000000020', 'B', 'Bacterial pathogens causing gastrointestinal infection', false, 'Ruled out because FIT is not a test for infective organisms; it specifically detects human haemoglobin as a marker of possible occult bleeding.', 2),
('f6000000-0000-0000-0000-000000000020', 'C', 'Human haemoglobin in the stool, indicating possible occult gastrointestinal bleeding', true, 'Correct. The faecal immunochemical test specifically detects human haemoglobin in stool samples, providing a sensitive method for identifying occult (not visible) gastrointestinal bleeding, which can be an early sign of colorectal cancer or significant polyps, prompting further investigation (colonoscopy) if positive.', 3),
('f6000000-0000-0000-0000-000000000020', 'D', 'Pancreatic enzyme levels reflecting exocrine function', false, 'Ruled out because FIT has no role in assessing pancreatic function; it is specifically a test for occult blood (haemoglobin) related to colorectal screening.', 4),
('f6000000-0000-0000-0000-000000000020', 'E', 'Direct visualisation of colonic polyps', false, 'Ruled out because FIT is a stool-based biochemical test, not an imaging or direct visualisation method; colonoscopy (a separate investigation) is used for direct visualisation following a positive FIT result.', 5),
('f6000000-0000-0000-0000-000000000021', 'A', 'HLA-B27', false, 'Ruled out because HLA-B27 is associated with seronegative spondyloarthropathies, entirely unrelated to hereditary breast and ovarian cancer risk.', 1),
('f6000000-0000-0000-0000-000000000021', 'B', 'Factor V Leiden', false, 'Ruled out because Factor V Leiden is associated with inherited thrombophilia, not hereditary breast and ovarian cancer risk.', 2),
('f6000000-0000-0000-0000-000000000021', 'C', 'HFE gene', false, 'Ruled out because the HFE gene is associated with hereditary haemochromatosis, not hereditary breast and ovarian cancer.', 3),
('f6000000-0000-0000-0000-000000000021', 'D', 'BRCA1 and BRCA2', true, 'Correct. A strong family history of early-onset breast and ovarian cancer is characteristic of hereditary breast and ovarian cancer syndrome, most commonly caused by pathogenic variants in BRCA1 or BRCA2, which significantly increase lifetime risk of these cancers; genetic testing for these genes, alongside genetic counselling, is appropriate given this family history pattern.', 4),
('f6000000-0000-0000-0000-000000000021', 'E', 'APOE', false, $x$Ruled out because APOE genotype is associated with Alzheimer's disease risk, not hereditary breast and ovarian cancer.$x$, 5),
('f6000000-0000-0000-0000-000000000022', 'A', 'Immediate referral for colposcopy regardless of cytology result', false, 'Ruled out because with normal cytology alongside HPV positivity, the standard pathway is earlier repeat testing rather than immediate colposcopy referral, which is reserved for abnormal cytology or persistent HPV positivity over subsequent tests.', 1),
('f6000000-0000-0000-0000-000000000022', 'B', 'No further action needed for at least 5 years, as per the standard screening interval', false, 'Ruled out because a positive high-risk HPV result specifically warrants earlier repeat testing (rather than waiting for the standard routine interval) to monitor for viral clearance or persistence.', 2),
('f6000000-0000-0000-0000-000000000022', 'C', 'Repeat HPV testing at an earlier interval (typically 12 months) to check for viral clearance', true, 'Correct. In HPV primary cervical screening programmes, a high-risk HPV positive result with normal cytology prompts earlier repeat testing (commonly at 12 months) to check whether the HPV infection has cleared, given that most HPV infections are transient; persistent HPV positivity at repeat testing would prompt referral for colposcopy.', 3),
('f6000000-0000-0000-0000-000000000022', 'D', 'Immediate hysterectomy as a precautionary measure', false, 'Ruled out because this is a vastly disproportionate response to a positive HPV test with normal cytology; the appropriate pathway is monitoring via earlier repeat testing, not surgery.', 4),
('f6000000-0000-0000-0000-000000000022', 'E', 'Empirical antiviral treatment for HPV', false, 'Ruled out because there is no specific antiviral treatment for HPV infection itself; management follows the structured screening/surveillance pathway (repeat testing, colposcopy if persistent or with abnormal cytology) rather than antiviral drug treatment.', 5),
('f6000000-0000-0000-0000-000000000023', 'A', 'CA 19-9 is not validated as a population screening test due to insufficient sensitivity and specificity, and is used instead for monitoring known pancreatic cancer', true, 'Correct. CA 19-9 lacks sufficient sensitivity and specificity to be used as a population-level screening test for pancreatic cancer in asymptomatic individuals (it can be falsely negative in some patients, and raised by various benign conditions); it is used clinically to help monitor disease response and detect recurrence in patients with a confirmed pancreatic cancer diagnosis, not for population screening.', 1),
('f6000000-0000-0000-0000-000000000023', 'B', 'CA 19-9 is an excellent, validated screening test that should be used routinely in the general population', false, 'Ruled out because CA 19-9 does not have adequate performance characteristics to be recommended as a population screening test; its clinical utility is primarily in monitoring established disease.', 2),
('f6000000-0000-0000-0000-000000000023', 'C', 'CA 19-9 can definitively diagnose or exclude pancreatic cancer on its own', false, 'Ruled out because CA 19-9 alone cannot definitively diagnose or exclude pancreatic cancer; it lacks sufficient sensitivity and specificity for this purpose and must be interpreted alongside clinical assessment and imaging.', 3),
('f6000000-0000-0000-0000-000000000023', 'D', 'CA 19-9 has no clinical use at all in pancreatic cancer management', false, 'Ruled out because although not suitable for screening, CA 19-9 does have a genuine clinical role in monitoring treatment response and detecting recurrence in patients with a confirmed pancreatic cancer diagnosis.', 4),
('f6000000-0000-0000-0000-000000000023', 'E', 'CA 19-9 should be used to screen the entire population regardless of family history or symptoms', false, 'Ruled out because this test is not recommended for population-wide screening given its limitations; testing decisions should be guided by clinical assessment and appropriate specialist pathways, not indiscriminate population screening.', 5),
('f6000000-0000-0000-0000-000000000024', 'A', $x$Purely for research purposes with no clinical relevance to this patient's care$x$, false, 'Ruled out because these molecular tests have direct, established clinical relevance to treatment selection and hereditary syndrome identification, not purely research application.', 1),
('f6000000-0000-0000-0000-000000000024', 'B', 'To guide personalised treatment decisions and identify potential hereditary cancer syndromes', true, 'Correct. Molecular tumour profiling (e.g. microsatellite instability status, specific gene mutations such as KRAS or BRAF in colorectal cancer) helps guide personalised treatment decisions (predicting response to certain targeted therapies or immunotherapy) and can identify tumours suggestive of an underlying hereditary cancer syndrome (e.g. Lynch syndrome, associated with MSI-high tumours), prompting further genetic assessment.', 2),
('f6000000-0000-0000-0000-000000000024', 'C', 'To determine the exact stage of the cancer', false, 'Ruled out because cancer staging is determined through clinical, radiological and pathological assessment (tumour size, nodal involvement, metastases), not primarily through this type of molecular marker testing, though molecular findings can complement overall assessment.', 3),
('f6000000-0000-0000-0000-000000000024', 'D', 'To replace the need for any imaging or histopathological assessment', false, 'Ruled out because molecular profiling complements, rather than replaces, standard imaging and histopathological assessment, which remain essential for diagnosis and staging.', 4),
('f6000000-0000-0000-0000-000000000024', 'E', 'To determine blood type compatibility for potential transfusion', false, 'Ruled out because this has no relationship to blood type/transfusion compatibility testing, which is an entirely separate process.', 5),
('f6000000-0000-0000-0000-000000000025', 'A', 'A normal, expected finding requiring no further action or investigation', false, 'Ruled out because a rising PSA during treatment for known prostate cancer is a clinically significant finding requiring further assessment, not something to be disregarded as normal or inconsequential.', 1),
('f6000000-0000-0000-0000-000000000025', 'B', 'Definitive evidence that treatment has completely failed and no further options exist', false, 'Ruled out because a rising PSA prompts further assessment to guide next steps, which may still include effective further treatment options; it does not necessarily mean all treatment options have been exhausted.', 2),
('f6000000-0000-0000-0000-000000000025', 'C', 'An indication that the cancer has been completely cured', false, 'Ruled out because a rising (rather than falling or stable/undetectable) PSA is the opposite of what would be expected with successful treatment; it suggests possible recurrence or progression, not cure.', 3),
('f6000000-0000-0000-0000-000000000025', 'D', 'Evidence of an unrelated urinary tract infection requiring antibiotics as the primary response', false, 'Ruled out because although infection can sometimes transiently affect PSA, the primary and most clinically important consideration for a rising PSA in a patient with known prostate cancer is possible disease recurrence/progression, requiring oncological assessment.', 4),
('f6000000-0000-0000-0000-000000000025', 'E', 'Possible disease progression or biochemical recurrence, warranting further assessment', true, 'Correct. A rising PSA during treatment for known prostate cancer is a key indicator of possible biochemical recurrence or disease progression, prompting further clinical assessment and potentially imaging to evaluate the extent of disease and guide treatment decisions.', 5),
('f6000000-0000-0000-0000-000000000026', 'A', 'Standard-dose chest X-ray', false, 'Ruled out because chest X-ray has not demonstrated the same mortality benefit as low-dose CT for lung cancer screening and is not the modality used in evidence-based lung cancer screening programmes.', 1),
('f6000000-0000-0000-0000-000000000026', 'B', 'PET-CT as the primary screening tool', false, 'Ruled out because PET-CT is not used as the primary screening modality; it involves higher radiation exposure and cost, and is more appropriately used for further characterisation of suspicious findings, not initial population screening.', 2),
('f6000000-0000-0000-0000-000000000026', 'C', 'Sputum cytology as the primary screening tool', false, 'Ruled out because sputum cytology has not been shown to provide the mortality benefit seen with low-dose CT and is not the standard modality used in current lung cancer screening programmes.', 3),
('f6000000-0000-0000-0000-000000000026', 'D', 'Bronchoscopy as the primary screening tool', false, 'Ruled out because bronchoscopy is an invasive procedure used for further diagnostic assessment of specific suspicious findings, not as a primary population screening tool.', 4),
('f6000000-0000-0000-0000-000000000026', 'E', 'Low-dose CT chest', true, 'Correct. Low-dose CT chest is the imaging modality used for lung cancer screening in high-risk populations (typically defined by significant smoking history and age range), shown in trials to reduce lung cancer mortality by detecting cancers at an earlier, more treatable stage compared with no screening or chest X-ray.', 5),
('f6000000-0000-0000-0000-000000000027', 'A', 'Doxorubicin has no cardiac effects; monitoring is purely precautionary with no specific rationale', false, 'Ruled out because anthracycline cardiotoxicity is a well-established, clinically significant and specifically monitored risk, not a purely precautionary measure without a defined rationale.', 1),
('f6000000-0000-0000-0000-000000000027', 'B', 'This monitoring is for detecting pulmonary, not cardiac, toxicity', false, 'Ruled out because echocardiography specifically assesses cardiac structure and function; the monitoring here is specifically for the recognised cardiotoxic risk of anthracyclines, not a pulmonary toxicity assessment.', 2),
('f6000000-0000-0000-0000-000000000027', 'C', 'This monitoring is to assess for bone marrow suppression', false, 'Ruled out because bone marrow suppression is monitored via full blood count, not echocardiography; cardiac imaging specifically addresses the cardiotoxicity risk of this drug class.', 3),
('f6000000-0000-0000-0000-000000000027', 'D', 'Anthracyclines such as doxorubicin carry a dose-dependent risk of cardiotoxicity, including cardiomyopathy and heart failure', true, 'Correct. Anthracycline chemotherapy agents (doxorubicin, epirubicin) carry a recognised, cumulative dose-dependent risk of cardiotoxicity, potentially causing dilated cardiomyopathy and heart failure; regular monitoring of cardiac function (e.g. echocardiography, assessing left ventricular ejection fraction) helps detect early cardiac dysfunction and guide decisions about continuing or modifying treatment.', 4),
('f6000000-0000-0000-0000-000000000027', 'E', 'This monitoring has no relevance to chemotherapy and is done for an unrelated reason', false, 'Ruled out because this monitoring is directly and specifically related to the known cardiotoxic risk profile of anthracycline chemotherapy.', 5),
('f6000000-0000-0000-0000-000000000028', 'A', 'Cisplatin is directly nephrotoxic, and adequate hydration reduces the risk of acute kidney injury', true, 'Correct. Cisplatin has well-recognised direct nephrotoxic effects on the renal tubules; adequate pre- and post-treatment hydration helps maintain renal perfusion and promote drug clearance, reducing the risk of cisplatin-induced acute kidney injury, alongside regular monitoring of renal function to detect any decline.', 1),
('f6000000-0000-0000-0000-000000000028', 'B', 'Cisplatin has no renal effects; this protocol is purely precautionary', false, 'Ruled out because cisplatin nephrotoxicity is a well-established, clinically significant and specifically managed risk, not a precautionary measure without a defined pharmacological rationale.', 2),
('f6000000-0000-0000-0000-000000000028', 'C', 'This protocol is to prevent cardiotoxicity, not nephrotoxicity', false, 'Ruled out because although cisplatin can have some cardiovascular effects, the specific, well-established rationale for hydration and renal monitoring relates directly to its nephrotoxic potential.', 3),
('f6000000-0000-0000-0000-000000000028', 'D', 'This protocol is to prevent hearing loss', false, 'Ruled out because although cisplatin is also associated with ototoxicity (a separate, important monitored side effect), the specific hydration protocol described is aimed at reducing nephrotoxicity, not ototoxicity, which is monitored separately (e.g. audiometry).', 4),
('f6000000-0000-0000-0000-000000000028', 'E', 'This protocol is unrelated to any recognised cisplatin toxicity', false, $x$Ruled out because this protocol is specifically and directly related to cisplatin's well-documented nephrotoxic potential.$x$, 5),
('f6000000-0000-0000-0000-000000000029', 'A', 'Simple age-related hearing loss unrelated to treatment', false, 'Ruled out because the clear temporal relationship to cisplatin treatment, a drug with well-documented ototoxic potential, makes drug-induced ototoxicity the more likely explanation than coincidental age-related change.', 1),
('f6000000-0000-0000-0000-000000000029', 'B', 'Otitis media', false, 'Ruled out because there is no mention of ear pain, discharge or infective features; the pattern described (bilateral, high-frequency loss with tinnitus during cisplatin treatment) is characteristic of drug-induced ototoxicity, not infection.', 2),
('f6000000-0000-0000-0000-000000000029', 'C', 'Cisplatin-induced ototoxicity', true, 'Correct. Cisplatin is a recognised cause of ototoxicity, typically causing bilateral, high-frequency sensorineural hearing loss and tinnitus, related to damage to cochlear hair cells; this can be irreversible, making baseline and periodic audiometric monitoring important during treatment, particularly with higher cumulative doses.', 3),
('f6000000-0000-0000-0000-000000000029', 'D', $x$Meniere's disease$x$, false, $x$Ruled out because Meniere's disease typically causes episodic vertigo with fluctuating hearing loss and aural fullness, a different pattern from the cisplatin-associated ototoxicity described here, and would not be specifically linked to the chemotherapy timing.$x$, 4),
('f6000000-0000-0000-0000-000000000029', 'E', 'Acoustic neuroma', false, 'Ruled out because although acoustic neuroma can cause unilateral hearing loss and tinnitus, the bilateral pattern and clear temporal relationship to cisplatin treatment point specifically to drug-induced ototoxicity.', 5),
('f6000000-0000-0000-0000-000000000030', 'A', 'Vitamin B12 deficiency unrelated to treatment', false, 'Ruled out because although B12 deficiency also causes peripheral neuropathy, the clear temporal relationship to starting vincristine, a drug with well-documented neurotoxic potential, makes drug-induced neuropathy the more likely explanation here.', 1),
('f6000000-0000-0000-0000-000000000030', 'B', 'Vincristine-induced peripheral neuropathy', true, 'Correct. Vincristine (a vinca alkaloid) is well-recognised to cause a dose-dependent peripheral neuropathy, affecting both sensory function (numbness, tingling) and, with autonomic involvement, bowel motility (constipation), as well as fine motor coordination; this is a common, sometimes dose-limiting toxicity requiring monitoring and potential dose adjustment.', 2),
('f6000000-0000-0000-0000-000000000030', 'C', 'Diabetic peripheral neuropathy', false, 'Ruled out because there is no mention of diabetes, and the temporal relationship to vincristine treatment points to drug-induced neurotoxicity as the cause.', 3),
('f6000000-0000-0000-0000-000000000030', 'D', 'Guillain-Barre syndrome', false, 'Ruled out because GBS is an acute, typically post-infectious, rapidly progressive ascending weakness, a different pattern and mechanism from the gradual, dose-related peripheral neuropathy characteristic of vincristine.', 4),
('f6000000-0000-0000-0000-000000000030', 'E', 'Simple anxiety-related paraesthesia', false, 'Ruled out because the specific combination of sensory neuropathy, constipation (autonomic involvement) and fine motor difficulty, in the context of vincristine treatment, points to a specific, recognised drug toxicity rather than anxiety.', 5),
('f6000000-0000-0000-0000-000000000031', 'A', 'Bleomycin has no pulmonary effects; this precaution is unrelated to his chemotherapy', false, 'Ruled out because bleomycin pulmonary toxicity is a well-established, clinically significant risk specifically relevant to this perioperative oxygen precaution.', 1),
('f6000000-0000-0000-0000-000000000031', 'B', 'This precaution relates to preventing cardiac arrhythmias, not pulmonary toxicity', false, 'Ruled out because the specific rationale for avoiding high-concentration oxygen in patients with bleomycin exposure relates to pulmonary toxicity, not a cardiac arrhythmia concern.', 2),
('f6000000-0000-0000-0000-000000000031', 'C', 'Bleomycin causes pulmonary fibrosis and toxicity, and high concentrations of oxygen can precipitate or worsen bleomycin-induced lung injury', true, 'Correct. Bleomycin is associated with pulmonary toxicity, including pulmonary fibrosis; exposure to high concentrations of inspired oxygen (as can occur during anaesthesia) is a recognised trigger that can precipitate or significantly worsen bleomycin-induced lung injury, even sometime after treatment has finished, making avoidance of high-concentration oxygen an important perioperative precaution in patients with prior bleomycin exposure.', 3),
('f6000000-0000-0000-0000-000000000031', 'D', 'This precaution is to prevent nephrotoxicity', false, $x$Ruled out because this specific oxygen-related precaution relates to bleomycin's pulmonary toxicity risk, not a renal concern.$x$, 4),
('f6000000-0000-0000-0000-000000000031', 'E', 'This precaution is a routine measure unrelated to any specific drug toxicity', false, $x$Ruled out because this is a specific, well-recognised precaution directly related to bleomycin's known pulmonary toxicity profile, not a generic, unrelated anaesthetic practice.$x$, 5),
('f6000000-0000-0000-0000-000000000032', 'A', 'To directly enhance the anti-tumour effect of methotrexate', false, $x$Ruled out because folinic acid's role is specifically to rescue normal cells from toxicity, not to enhance the anti-tumour effect; in fact, if given too early or in excess, it could theoretically reduce anti-tumour efficacy, which is why timing is carefully protocolised.$x$, 1),
('f6000000-0000-0000-0000-000000000032', 'B', 'To treat methotrexate-induced nausea', false, $x$Ruled out because folinic acid rescue addresses the folate-related toxicity mechanism (protecting normal cells from methotrexate's antifolate effect), not specifically nausea, which is managed separately with antiemetics.$x$, 2),
('f6000000-0000-0000-0000-000000000032', 'C', 'To reverse methotrexate-induced nephrotoxicity directly', false, $x$Ruled out because although adequate hydration and urine alkalinisation are used to help prevent methotrexate-related renal toxicity, folinic acid's specific mechanism is folate replenishment to protect normal cells from the antifolate toxicity, not a direct renal protective action.$x$, 3),
('f6000000-0000-0000-0000-000000000032', 'D', 'To reduce methotrexate-related toxicity to normal cells by replenishing reduced folate, without significantly reducing anti-tumour effect', true, $x$Correct. Folinic acid (leucovorin) 'rescue' is given after high-dose methotrexate to replenish reduced folate in normal cells, protecting them from the toxic effects of methotrexate (which blocks dihydrofolate reductase), while the higher intracellular methotrexate concentration achieved in tumour cells means the anti-tumour effect is relatively preserved -- allowing higher, more effective methotrexate doses to be used with reduced risk of severe toxicity (e.g. mucositis, myelosuppression).$x$, 4),
('f6000000-0000-0000-0000-000000000032', 'E', 'To prevent methotrexate absorption in the gut', false, $x$Ruled out because folinic acid does not act by preventing absorption; its mechanism is providing reduced folate to rescue normal cells from methotrexate's intracellular antifolate effects.$x$, 5),
('f6000000-0000-0000-0000-000000000033', 'A', 'Simple anxiety related to receiving chemotherapy', false, 'Ruled out because the specific finding of ECG changes suggestive of ischaemia during infusion, in the context of a drug with recognised cardiotoxic potential, points to a genuine cardiac event (vasospasm) rather than simple anxiety.', 1),
('f6000000-0000-0000-0000-000000000033', 'B', 'Underlying severe coronary artery disease', false, 'Ruled out because his coronary arteries were specifically found to be normal on angiography, excluding significant fixed coronary artery disease as the explanation; the mechanism here is vasospasm, not atherosclerotic disease.', 2),
('f6000000-0000-0000-0000-000000000033', 'C', 'Pulmonary embolism', false, 'Ruled out because the ECG changes described are specifically suggestive of myocardial ischaemia, and the clear temporal relationship to 5-fluorouracil infusion with normal coronary angiography points to drug-induced coronary vasospasm rather than PE.', 3),
('f6000000-0000-0000-0000-000000000033', 'D', 'Simple musculoskeletal chest pain unrelated to treatment', false, 'Ruled out because ECG changes suggestive of ischaemia indicate a genuine cardiac event, not simple musculoskeletal pain, and the temporal relationship to a drug with recognised cardiotoxic potential is significant.', 4),
('f6000000-0000-0000-0000-000000000033', 'E', '5-fluorouracil-induced coronary vasospasm', true, 'Correct. 5-fluorouracil is a recognised, though less common than anthracycline, cause of cardiotoxicity, typically presenting as chest pain from coronary artery vasospasm during or shortly after infusion, sometimes with normal underlying coronary arteries on angiography; management involves stopping the infusion and considering alternative chemotherapy regimens if symptoms recur.', 5),
('f6000000-0000-0000-0000-000000000034', 'A', 'Hypertension, a recognised class side effect of certain tyrosine kinase inhibitors', true, 'Correct. Certain tyrosine kinase inhibitors are associated with new or worsening hypertension as a recognised class side effect, related to their effects on vascular signalling pathways; regular blood pressure monitoring allows early detection and appropriate management, alongside other routine monitoring (e.g. full blood count, liver function) relevant to this drug class.', 1),
('f6000000-0000-0000-0000-000000000034', 'B', 'Hypertension has no known association with tyrosine kinase inhibitors; this monitoring is unrelated', false, 'Ruled out because hypertension is a specifically recognised, monitored side effect of certain tyrosine kinase inhibitors, not an unrelated or coincidental monitoring practice.', 2),
('f6000000-0000-0000-0000-000000000034', 'C', 'This monitoring is specifically for detecting hypoglycaemia', false, 'Ruled out because blood pressure monitoring assesses cardiovascular parameters, not glucose levels; hypoglycaemia monitoring would involve blood glucose testing, not blood pressure.', 3),
('f6000000-0000-0000-0000-000000000034', 'D', 'This monitoring is unrelated to his cancer treatment and is purely routine primary care practice', false, 'Ruled out because this monitoring is specifically relevant to a recognised side effect of his ongoing targeted cancer therapy, not simply generic, unrelated primary care blood pressure checking.', 4),
('f6000000-0000-0000-0000-000000000034', 'E', 'This monitoring is to assess for anaemia', false, 'Ruled out because anaemia is assessed via full blood count, not blood pressure measurement; blood pressure monitoring here relates specifically to the hypertension risk associated with this drug class.', 5),
('f6000000-0000-0000-0000-000000000035', 'A', 'A further, different 5-HT3 receptor antagonist added to the existing one', false, 'Ruled out because combining two drugs from the same class (5-HT3 antagonists) does not provide meaningful additional benefit; adding a drug with a different mechanism of action (such as an NK1 antagonist) is the more appropriate escalation strategy.', 1),
('f6000000-0000-0000-0000-000000000035', 'B', 'Neurokinin-1 (NK1) receptor antagonist (e.g. aprepitant)', true, 'Correct. For chemotherapy-induced nausea and vomiting inadequately controlled by a 5-HT3 receptor antagonist and dexamethasone (the standard combination for highly emetogenic regimens), adding an NK1 receptor antagonist provides an additional, complementary mechanism of antiemetic action, particularly useful for both acute and delayed nausea/vomiting.', 2),
('f6000000-0000-0000-0000-000000000035', 'C', 'Stopping all antiemetics, as they are clearly ineffective', false, 'Ruled out because stopping antiemetics entirely would likely worsen, not improve, his symptoms; the appropriate approach is to escalate/add complementary antiemetic classes, not withdraw treatment.', 3),
('f6000000-0000-0000-0000-000000000035', 'D', 'High-dose opioid analgesia as an antiemetic strategy', false, 'Ruled out because opioids are not a standard antiemetic strategy for chemotherapy-induced nausea and vomiting and can themselves cause nausea as a side effect.', 4),
('f6000000-0000-0000-0000-000000000035', 'E', 'Simple reassurance with no medication changes', false, 'Ruled out because inadequately controlled chemotherapy-induced nausea and vomiting significantly impacts quality of life and can affect treatment adherence, warranting active escalation of antiemetic therapy rather than reassurance alone.', 5),
('f6000000-0000-0000-0000-000000000036', 'A', 'After completing all chemotherapy, once treatment is finished', false, 'Ruled out because most fertility preservation options (e.g. egg/embryo cryopreservation) need to be undertaken before gonadotoxic treatment starts, as the eggs/ovarian reserve would already be affected by chemotherapy if delayed until after treatment.', 1),
('f6000000-0000-0000-0000-000000000036', 'B', 'This discussion is not relevant or necessary for cancer patients', false, 'Ruled out because fertility preservation is a recognised, important consideration for patients of reproductive age facing potentially gonadotoxic cancer treatment, and should be proactively discussed, not omitted.', 2),
('f6000000-0000-0000-0000-000000000036', 'C', 'Before starting chemotherapy, allowing time to consider and potentially pursue fertility preservation options', true, 'Correct. Fertility preservation counselling and options (e.g. egg or embryo cryopreservation) should be discussed before starting gonadotoxic chemotherapy, as treatment can cause temporary or permanent infertility, and fertility preservation procedures generally need to be arranged and completed before chemotherapy begins to be effective.', 3),
('f6000000-0000-0000-0000-000000000036', 'D', 'Only relevant if the patient specifically raises the topic themselves', false, 'Ruled out because proactive discussion of fertility implications and preservation options is recommended as part of routine pre-treatment counselling for patients of reproductive age, rather than relying solely on the patient to raise it.', 4),
('f6000000-0000-0000-0000-000000000036', 'E', 'Only relevant for male patients, not female patients', false, 'Ruled out because fertility preservation is relevant to both male (e.g. sperm banking) and female (e.g. egg/embryo cryopreservation) patients facing gonadotoxic chemotherapy, not exclusively one sex.', 5),
('f6000000-0000-0000-0000-000000000037', 'A', 'Chemotherapy-induced hair loss is usually temporary, with regrowth typically starting within a few months of completing treatment', true, 'Correct. Hair loss (alopecia) from chemotherapy, resulting from toxic effects on rapidly dividing hair follicle cells, is usually reversible, with hair typically starting to regrow within a few months after completing treatment, though texture or colour may sometimes differ initially; scalp cooling during treatment can help reduce the severity of hair loss for some regimens.', 1),
('f6000000-0000-0000-0000-000000000037', 'B', 'This hair loss is permanent and will never regrow', false, 'Ruled out because chemotherapy-induced alopecia is typically reversible for most regimens, with hair regrowth expected after treatment completion, though this should still be discussed sensitively as an individual concern.', 2),
('f6000000-0000-0000-0000-000000000037', 'C', 'This represents an allergic reaction requiring immediate treatment discontinuation', false, 'Ruled out because alopecia is an expected, common toxicity of many chemotherapy regimens related to their mechanism of action on rapidly dividing cells, not an allergic reaction requiring treatment to be stopped.', 3),
('f6000000-0000-0000-0000-000000000037', 'D', 'Hair loss only occurs with a very small number of unusual chemotherapy regimens', false, 'Ruled out because alopecia is a common side effect across many standard chemotherapy regimens, not a rare occurrence limited to unusual treatments.', 4),
('f6000000-0000-0000-0000-000000000037', 'E', 'Nothing can be done to reduce the severity of hair loss during treatment', false, 'Ruled out because scalp cooling techniques, used during chemotherapy infusion for certain regimens, can help reduce the severity of hair loss for some patients, providing a potential supportive option to discuss.', 5),
('f6000000-0000-0000-0000-000000000038', 'A', 'A new, unrelated diagnosis of aplastic anaemia', false, 'Ruled out because this pancytopenia occurring at the expected timeframe following chemotherapy is most consistent with anticipated treatment-related myelosuppression, not a new, separate diagnosis of aplastic anaemia.', 1),
('f6000000-0000-0000-0000-000000000038', 'B', 'Disease progression causing bone marrow infiltration', false, 'Ruled out because although marrow infiltration from disease progression is a differential to consider in some contexts, the clear temporal relationship to recent chemotherapy at the expected nadir timing makes treatment-related myelosuppression the most likely explanation.', 2),
('f6000000-0000-0000-0000-000000000038', 'C', 'A normal blood count requiring no specific consideration', false, 'Ruled out because significant pancytopenia, even if expected, requires active monitoring and appropriate precautions (e.g. infection risk awareness, transfusion support if needed), not being disregarded as entirely unremarkable.', 3),
('f6000000-0000-0000-0000-000000000038', 'D', 'An allergic reaction to the chemotherapy', false, 'Ruled out because myelosuppression is a direct, expected pharmacological effect of many chemotherapy agents on the bone marrow, not an allergic hypersensitivity reaction.', 4),
('f6000000-0000-0000-0000-000000000038', 'E', 'Expected chemotherapy-induced myelosuppression (bone marrow suppression) at the anticipated nadir', true, 'Correct. Most cytotoxic chemotherapy agents suppress bone marrow production of blood cells, with the lowest point (nadir) typically occurring around 7-14 days after treatment, depending on the specific regimen; this expected myelosuppression requires monitoring (full blood count) and appropriate precautions (e.g. awareness of infection risk, transfusion support if needed) during this vulnerable period.', 5),
('f6000000-0000-0000-0000-000000000039', 'A', 'Direct tumour invasion of the pituitary gland', false, 'Ruled out because SIADH in this context results from ectopic hormone secretion by the tumour itself, not from direct pituitary invasion or destruction.', 1),
('f6000000-0000-0000-0000-000000000039', 'B', 'Simple dehydration causing hyponatraemia', false, 'Ruled out because dehydration would cause hypovolaemic (not euvolaemic) hyponatraemia with appropriately (not inappropriately) concentrated urine reflecting a normal renal response to volume depletion.', 2),
('f6000000-0000-0000-0000-000000000039', 'C', 'Primary adrenal insufficiency', false, 'Ruled out because although this can cause hyponatraemia, it is typically accompanied by hyperkalaemia and hypotension from combined glucocorticoid/mineralocorticoid deficiency, not the isolated euvolaemic hyponatraemia pattern with concentrated urine seen in SIADH.', 3),
('f6000000-0000-0000-0000-000000000039', 'D', 'Ectopic ADH secretion from a small cell lung cancer causing SIADH', true, 'Correct. Small cell lung cancer is a classic cause of paraneoplastic SIADH, secreting ectopic ADH (or ADH-like peptides) causing euvolaemic hyponatraemia with inappropriately concentrated urine, explaining his confusion and lethargy.', 4),
('f6000000-0000-0000-0000-000000000039', 'E', 'Excessive water intake (primary polydipsia)', false, 'Ruled out because primary polydipsia would cause appropriately dilute (not concentrated) urine as the kidneys attempt to excrete the excess free water, the opposite of the SIADH pattern described here.', 5),
('f6000000-0000-0000-0000-000000000040', 'A', 'Myasthenia gravis', false, 'Ruled out because myasthenia gravis causes fatigable weakness that worsens (not improves) with sustained activity, and typically affects ocular/bulbar muscles prominently, the opposite pattern to the post-tetanic potentiation and proximal limb predominance described here.', 1),
('f6000000-0000-0000-0000-000000000040', 'B', 'Lambert-Eaton myasthenic syndrome', true, 'Correct. Proximal muscle weakness, autonomic symptoms (dry mouth), and post-tetanic potentiation of reflexes (initially reduced, improving after sustained contraction) in a patient with small cell lung cancer is characteristic of Lambert-Eaton myasthenic syndrome, a paraneoplastic disorder caused by antibodies against presynaptic voltage-gated calcium channels, impairing acetylcholine release at the neuromuscular junction.', 2),
('f6000000-0000-0000-0000-000000000040', 'C', 'Guillain-Barre syndrome', false, 'Ruled out because GBS is an acute, typically post-infectious, progressive ascending weakness, not this chronic pattern with post-tetanic potentiation and paraneoplastic association.', 3),
('f6000000-0000-0000-0000-000000000040', 'D', 'Motor neuron disease', false, 'Ruled out because MND causes a mix of upper and lower motor neuron signs without autonomic involvement or the characteristic reflex facilitation seen here.', 4),
('f6000000-0000-0000-0000-000000000040', 'E', 'Simple age-related muscle weakness', false, 'Ruled out because the specific pattern (post-tetanic potentiation, autonomic symptoms) and association with an underlying malignancy indicate a specific paraneoplastic syndrome, not simple age-related change.', 5),
('f6000000-0000-0000-0000-000000000041', 'A', 'Secretion of parathyroid hormone-related protein (PTHrP) by the tumour', true, 'Correct. Squamous cell carcinomas (particularly of the lung) are a classic cause of humoral hypercalcaemia of malignancy, mediated by tumour secretion of PTHrP, which mimics PTH action on bone and kidney to raise calcium, while appropriately suppressing endogenous PTH secretion via negative feedback from the resulting hypercalcaemia.', 1),
('f6000000-0000-0000-0000-000000000041', 'B', 'Direct bone metastasis causing osteolytic hypercalcaemia', false, 'Ruled out because although bone metastases can cause hypercalcaemia through local osteolysis, the specific mechanism most classically associated with squamous cell lung cancer (even without extensive bone metastases) is humoral hypercalcaemia via PTHrP secretion.', 2),
('f6000000-0000-0000-0000-000000000041', 'C', 'Primary hyperparathyroidism', false, 'Ruled out because primary hyperparathyroidism would show a raised (not suppressed) PTH level, the opposite of the biochemical pattern described here.', 3),
('f6000000-0000-0000-0000-000000000041', 'D', 'Vitamin D toxicity', false, 'Ruled out because there is no history of excess vitamin D intake, and the clinical context (known squamous cell lung cancer) points to a paraneoplastic mechanism (PTHrP) rather than vitamin D toxicity.', 4),
('f6000000-0000-0000-0000-000000000041', 'E', 'Excessive dietary calcium intake', false, 'Ruled out because dietary calcium intake alone rarely causes hypercalcaemia of this severity, and the clear malignancy context points to a paraneoplastic mechanism.', 5),
('f6000000-0000-0000-0000-000000000042', 'A', 'Simple viral encephalitis unrelated to her teratoma', false, 'Ruled out because although a preceding viral-like illness can occur, the specific combination of psychiatric symptoms, seizures, dyskinesias and autonomic instability, together with the known ovarian teratoma, points specifically to anti-NMDA receptor encephalitis rather than a straightforward viral process.', 1),
('f6000000-0000-0000-0000-000000000042', 'B', 'Primary psychiatric disorder unrelated to any underlying medical cause', false, 'Ruled out because the combination of seizures, abnormal movements and autonomic instability, alongside psychiatric symptoms, indicates an organic neurological process (autoimmune encephalitis), not a primary psychiatric disorder.', 2),
('f6000000-0000-0000-0000-000000000042', 'C', 'Simple epilepsy unrelated to malignancy', false, 'Ruled out because although seizures are a feature, the broader combination of psychiatric symptoms, movement abnormalities and autonomic instability, with the specific tumour association, points to a paraneoplastic autoimmune encephalitis rather than isolated primary epilepsy.', 3),
('f6000000-0000-0000-0000-000000000042', 'D', 'Anti-NMDA receptor encephalitis', true, 'Correct. Rapidly progressive psychiatric symptoms, seizures, abnormal movements (dyskinesias) and autonomic instability, often following a preceding viral-like prodrome, in a patient with an ovarian teratoma, is characteristic of anti-NMDA receptor encephalitis, a paraneoplastic autoimmune encephalitis caused by antibodies against NMDA receptors, often associated with this specific tumour type.', 4),
('f6000000-0000-0000-0000-000000000042', 'E', $x$Wernicke's encephalopathy$x$, false, $x$Ruled out because Wernicke's encephalopathy causes the triad of confusion, ataxia and ophthalmoplegia related to thiamine deficiency, a different pattern from the psychiatric symptoms, seizures, dyskinesias and autonomic instability described here, and is not specifically linked to ovarian teratoma.$x$, 5),
('f6000000-0000-0000-0000-000000000043', 'A', 'Cerebellar stroke', false, 'Ruled out because a stroke would typically show an abnormality on MRI and present more acutely, unlike this progressive, subacute course with a normal MRI and specific paraneoplastic antibody found here.', 1),
('f6000000-0000-0000-0000-000000000043', 'B', 'Multiple sclerosis', false, 'Ruled out because MS would typically show characteristic demyelinating lesions on MRI, not a normal scan, and would not be specifically associated with anti-Yo antibodies.', 2),
('f6000000-0000-0000-0000-000000000043', 'C', 'Alcohol-related cerebellar degeneration', false, 'Ruled out because there is no alcohol history given, and the specific positive anti-Yo antibody in the context of known malignancy points to a paraneoplastic, not alcohol-related, cause.', 3),
('f6000000-0000-0000-0000-000000000043', 'D', 'Vitamin B12 deficiency', false, 'Ruled out because B12 deficiency causes a combined peripheral neuropathy and posterior column/corticospinal tract picture (subacute combined degeneration), not this specific cerebellar syndrome with anti-Yo antibody positivity.', 4),
('f6000000-0000-0000-0000-000000000043', 'E', 'Paraneoplastic cerebellar degeneration', true, 'Correct. Progressive cerebellar dysfunction (ataxia, dysarthria, limb incoordination) with a normal MRI and positive anti-Yo antibodies, in a patient with breast (or gynaecological) cancer, is characteristic of paraneoplastic cerebellar degeneration, an antibody-mediated paraneoplastic neurological syndrome causing Purkinje cell loss.', 5),
('f6000000-0000-0000-0000-000000000044', 'A', 'Dermatomyositis is itself a form of cancer requiring staging', false, 'Ruled out because dermatomyositis is an autoimmune inflammatory myopathy, not a malignancy itself; screening is performed because of its recognised association with a separate, underlying cancer, not because the condition itself is cancerous.', 1),
('f6000000-0000-0000-0000-000000000044', 'B', 'This screening is purely coincidental with no genuine underlying association', false, 'Ruled out because there is a genuine, well-documented paraneoplastic-type association between dermatomyositis and malignancy, not simply coincidental screening practice.', 2),
('f6000000-0000-0000-0000-000000000044', 'C', 'Dermatomyositis, particularly in adults, has a well-established association with underlying occult malignancy', true, 'Correct. Adult-onset dermatomyositis carries a significantly increased risk of an underlying malignancy (particularly ovarian, lung, pancreatic, gastric and colorectal cancers, and lymphoma) around the time of diagnosis, making age- and risk-appropriate cancer screening an important part of the initial workup, as dermatomyositis can itself represent a paraneoplastic phenomenon.', 3),
('f6000000-0000-0000-0000-000000000044', 'D', 'This association applies equally to polymyositis, with no difference between the two conditions', false, 'Ruled out because the malignancy association is notably stronger in dermatomyositis than in polymyositis, an important distinguishing feature between these two related but distinct inflammatory myopathies.', 4),
('f6000000-0000-0000-0000-000000000044', 'E', 'There is no genuine increased cancer risk; this is an outdated, unsupported practice', false, 'Ruled out because the association between adult dermatomyositis and malignancy is well-supported by evidence and remains current standard practice guiding screening recommendations.', 5),
('f6000000-0000-0000-0000-000000000045', 'A', 'Spinal cord compression from vertebral metastases', false, 'Ruled out because MRI has specifically excluded a spinal cord lesion, and the nerve conduction study findings confirm a peripheral (not central/cord) neuropathic process.', 1),
('f6000000-0000-0000-0000-000000000045', 'B', 'Paraneoplastic peripheral neuropathy', true, 'Correct. A subacute, progressive sensorimotor peripheral neuropathy, without evidence of a structural spinal cord lesion, occurring in the context of an underlying malignancy, can represent a paraneoplastic peripheral neuropathy, one of several possible paraneoplastic neurological syndromes, though other causes (chemotherapy-related, nutritional, diabetic) should also be considered and excluded as appropriate.', 2),
('f6000000-0000-0000-0000-000000000045', 'C', 'Simple age-related peripheral neuropathy unrelated to his cancer', false, 'Ruled out because although age-related changes can contribute to neuropathy, the temporal association with his cancer diagnosis and the specific pattern described should prompt consideration of a paraneoplastic mechanism, alongside other relevant causes.', 3),
('f6000000-0000-0000-0000-000000000045', 'D', 'Multiple sclerosis', false, 'Ruled out because MS is a central (not peripheral) demyelinating disease and would not explain this peripheral nerve conduction study pattern.', 4),
('f6000000-0000-0000-0000-000000000045', 'E', 'Simple vitamin B12 deficiency unrelated to his malignancy', false, 'Ruled out because although B12 deficiency should be considered and excluded as part of the workup, the clinical context (known malignancy) also raises specific consideration of a paraneoplastic mechanism, which should be actively considered alongside other differentials.', 5),
('f6000000-0000-0000-0000-000000000046', 'A', 'Polycythaemia vera occurring coincidentally', false, 'Ruled out because although this remains a differential to formally exclude, the strong specific association between renal cell carcinoma and paraneoplastic erythrocytosis via ectopic erythropoietin makes this the more likely explanation in this context, particularly if JAK2 mutation testing is negative.', 1),
('f6000000-0000-0000-0000-000000000046', 'B', 'Chronic hypoxia from underlying lung disease', false, 'Ruled out because there is no mention of chronic lung disease, and the known renal cell carcinoma provides a specific, well-recognised paraneoplastic explanation for the polycythaemia.', 2),
('f6000000-0000-0000-0000-000000000046', 'C', 'Dehydration causing relative polycythaemia', false, 'Ruled out because this would represent a relative (not true) polycythaemia from reduced plasma volume, whereas the paraneoplastic mechanism described here reflects true erythrocytosis from excess erythropoietin-driven red cell production.', 3),
('f6000000-0000-0000-0000-000000000046', 'D', 'Ectopic erythropoietin secretion by the renal cell carcinoma', true, 'Correct. Renal cell carcinoma is a recognised cause of paraneoplastic erythrocytosis (polycythaemia) through ectopic secretion of erythropoietin by the tumour, stimulating excess red cell production independent of the normal physiological regulatory mechanisms.', 4),
('f6000000-0000-0000-0000-000000000046', 'E', 'Anabolic steroid use', false, 'Ruled out because there is no history of anabolic steroid use given, and the known renal cell carcinoma provides a clear, relevant explanation via ectopic erythropoietin secretion.', 5),
('f6000000-0000-0000-0000-000000000047', 'A', 'Simple insulin-resistance-associated acanthosis nigricans unrelated to malignancy', false, 'Ruled out because although acanthosis nigricans is more commonly associated with insulin resistance/obesity, the rapid onset in an older patient with known malignancy is more characteristic of the paraneoplastic (malignant) form.', 1),
('f6000000-0000-0000-0000-000000000047', 'B', 'Normal skin change with ageing requiring no specific consideration', false, 'Ruled out because this represents a specific, recognised dermatological sign with potential clinical significance (association with internal malignancy), not a normal, inconsequential ageing change.', 2),
('f6000000-0000-0000-0000-000000000047', 'C', 'A simple contact dermatitis reaction', false, 'Ruled out because the specific symmetrical, velvety, hyperpigmented appearance in flexural areas is characteristic of acanthosis nigricans, not a contact dermatitis reaction.', 3),
('f6000000-0000-0000-0000-000000000047', 'D', 'A fungal skin infection', false, 'Ruled out because although flexural areas can be affected by fungal infections, the specific velvety, hyperpigmented thickening described is characteristic of acanthosis nigricans, not an infective process.', 4),
('f6000000-0000-0000-0000-000000000047', 'E', 'Malignant acanthosis nigricans, a cutaneous marker suggestive of an underlying internal malignancy', true, 'Correct. Acanthosis nigricans developing rapidly in an older, non-obese patient (in contrast to the more common, gradual, insulin-resistance-associated form) is a recognised paraneoplastic cutaneous sign, most classically associated with gastrointestinal adenocarcinomas (particularly gastric cancer, though also colorectal and other cancers), warranting consideration of an underlying malignancy if not already known.', 5),
('f6000000-0000-0000-0000-000000000048', 'A', 'Simple age-related macular degeneration', false, 'Ruled out because the rapid progression, photosensitivity, specific antibody findings and clear malignancy association point to a paraneoplastic process rather than typical age-related macular degeneration.', 1),
('f6000000-0000-0000-0000-000000000048', 'B', 'Diabetic retinopathy', false, 'Ruled out because there is no diabetes history given, and the specific antibody-mediated mechanism and rapid progression described are characteristic of cancer-associated retinopathy, not diabetic changes.', 2),
('f6000000-0000-0000-0000-000000000048', 'C', 'Cancer-associated retinopathy', true, 'Correct. Rapidly progressive visual loss with photosensitivity and retinal pigmentary changes, associated with anti-retinal antibodies, in a patient with small cell lung cancer, is characteristic of cancer-associated retinopathy, a rare paraneoplastic syndrome in which antibodies cross-react with retinal photoreceptor proteins, causing progressive visual dysfunction.', 3),
('f6000000-0000-0000-0000-000000000048', 'D', 'Retinal detachment', false, 'Ruled out because retinal detachment typically causes a specific pattern of visual field loss (curtain-like) from mechanical separation, not this antibody-mediated, bilateral, progressive pattern with photosensitivity.', 4),
('f6000000-0000-0000-0000-000000000048', 'E', 'Simple cataracts', false, 'Ruled out because cataracts cause gradual visual blurring from lens opacity, not this specific pattern of retinal pigmentary changes with photosensitivity and anti-retinal antibodies.', 5),
('f6000000-0000-0000-0000-000000000049', 'A', 'Ectopic ACTH secretion by the small cell lung cancer', true, $x$Correct. Small cell lung cancer is a classic cause of ectopic ACTH syndrome, in which the tumour secretes ACTH independently of normal pituitary regulation, driving excess adrenal cortisol production and producing the clinical features of Cushing's syndrome, often with a more rapid onset and more pronounced hypokalaemia than pituitary-dependent Cushing's disease.$x$, 1),
('f6000000-0000-0000-0000-000000000049', 'B', $x$A co-existing pituitary adenoma (Cushing's disease)$x$, false, $x$Ruled out because although Cushing's disease (pituitary ACTH-secreting adenoma) is a differential for ACTH-dependent Cushing's syndrome, the strong clinical context of known small cell lung cancer makes ectopic ACTH secretion by the tumour itself the most likely explanation here.$x$, 2),
('f6000000-0000-0000-0000-000000000049', 'C', 'Adrenal adenoma causing autonomous cortisol secretion', false, $x$Ruled out because adrenal-source (ACTH-independent) Cushing's syndrome would show a suppressed, not raised, ACTH level, the opposite of the biochemical pattern described here.$x$, 3),
('f6000000-0000-0000-0000-000000000049', 'D', 'Exogenous corticosteroid use', false, 'Ruled out because there is no history of steroid medication given, and the biochemical and clinical context (known small cell lung cancer with raised ACTH) points to ectopic ACTH secretion by the tumour.', 4),
('f6000000-0000-0000-0000-000000000049', 'E', 'Primary hyperaldosteronism', false, 'Ruled out because primary hyperaldosteronism causes hypertension with hypokalaemia from aldosterone excess, not the full Cushingoid picture with raised cortisol and ACTH described here.', 5),
('f6000000-0000-0000-0000-000000000050', 'A', 'Simple osteoarthritis', false, 'Ruled out because osteoarthritis does not cause clubbing or periosteal new bone formation on X-ray; this specific combination of findings is characteristic of hypertrophic pulmonary osteoarthropathy.', 1),
('f6000000-0000-0000-0000-000000000050', 'B', 'Hypertrophic pulmonary osteoarthropathy', true, 'Correct. Digital clubbing combined with painful periosteal new bone formation and joint swelling, in a patient with an underlying malignancy (classically lung cancer, though also seen with other thoracic and some non-thoracic malignancies), is characteristic of hypertrophic pulmonary osteoarthropathy, a paraneoplastic syndrome causing this specific combination of skeletal and digital changes.', 2),
('f6000000-0000-0000-0000-000000000050', 'C', 'Rheumatoid arthritis', false, 'Ruled out because although RA causes joint swelling, it does not cause clubbing or this specific periosteal reaction pattern on X-ray, which is characteristic of HPOA.', 3),
('f6000000-0000-0000-0000-000000000050', 'D', 'Gout', false, 'Ruled out because gout typically causes acute monoarthritis with urate crystals on aspiration, not this combination of bilateral clubbing with periosteal new bone formation.', 4),
('f6000000-0000-0000-0000-000000000050', 'E', 'Psoriatic arthritis', false, 'Ruled out because although psoriatic arthritis can cause dactylitis, it does not typically cause this specific combination of clubbing with periosteal new bone formation associated with an underlying malignancy.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('f6000000-0000-0000-0000-000000000001', 'Facial and neck swelling with distended neck veins reflects impaired venous return from the head, neck and arms due to obstruction of the superior vena cava.', 1),
('f6000000-0000-0000-0000-000000000001', $x$Dilated collateral veins over the chest wall reflect the body's attempt to bypass the obstruction via alternative venous pathways, a specific and useful clinical sign.$x$, 2),
('f6000000-0000-0000-0000-000000000001', 'Lung cancer and lymphoma are the most common malignant causes of SVC obstruction, reflecting the anatomical proximity of mediastinal structures to the SVC.', 3),
('f6000000-0000-0000-0000-000000000002', 'New bilateral leg weakness with a sensory level and bladder dysfunction in a patient with known or suspected malignancy should be treated as spinal cord compression until proven otherwise, given the time-critical nature of preserving neurological function.', 1),
('f6000000-0000-0000-0000-000000000002', 'High-dose dexamethasone is given immediately, even before imaging confirmation in strongly suspected cases, to reduce cord oedema and help preserve neurological function while definitive investigation and treatment are arranged.', 2),
('f6000000-0000-0000-0000-000000000002', 'Urgent MRI of the whole spine (not just the clinically suspected level) is required, as multiple levels of compression can coexist, which would affect surgical or radiotherapy planning.', 3),
('f6000000-0000-0000-0000-000000000003', 'Neutropenic sepsis (fever with a significantly reduced neutrophil count, typically below 0.5x10^9/L) in a patient on chemotherapy is a medical emergency given the impaired ability to fight infection and risk of rapid deterioration.', 1),
('f6000000-0000-0000-0000-000000000003', 'Empirical broad-spectrum antibiotics must be given immediately (typically within one hour), following local protocols, without waiting for culture confirmation, given the significant mortality risk of delay.', 2),
('f6000000-0000-0000-0000-000000000003', 'All patients on chemotherapy should be counselled to seek urgent medical attention for any fever, given the potential severity and rapid progression of neutropenic sepsis.', 3),
('f6000000-0000-0000-0000-000000000004', 'Severe hypercalcaemia (corrected calcium above approximately 3.5 mmol/L, or symptomatic at lower levels) constitutes a medical emergency requiring prompt treatment.', 1),
('f6000000-0000-0000-0000-000000000004', 'IV rehydration addresses the significant volume depletion typically present (from calcium-induced nephrogenic diabetes insipidus and vomiting), which itself worsens hypercalcaemia by reducing renal calcium clearance.', 2),
('f6000000-0000-0000-0000-000000000004', 'IV bisphosphonates provide more sustained calcium lowering by inhibiting osteoclast-mediated bone resorption, though they take 2-4 days to reach maximal effect, which is why rehydration is started immediately alongside.', 3),
('f6000000-0000-0000-0000-000000000005', 'High-risk features for tumour lysis syndrome include bulky disease, rapidly proliferating tumours (e.g. high-grade lymphoma, acute leukaemia), and pre-existing renal impairment, guiding the intensity of prophylactic measures used.', 1),
('f6000000-0000-0000-0000-000000000005', 'Adequate hydration promotes renal clearance of the potassium, phosphate and uric acid released from rapidly dying tumour cells, helping prevent the metabolic complications of tumour lysis syndrome.', 2),
('f6000000-0000-0000-0000-000000000005', 'Rasburicase (a recombinant uricase enzyme) is used for higher-risk patients, providing more effective uric acid reduction than allopurinol by directly breaking down existing uric acid, rather than simply preventing its further production.', 3),
('f6000000-0000-0000-0000-000000000006', 'Extensive hepatic metastatic replacement of functional liver parenchyma can cause acute liver failure, with the combination of encephalopathy, jaundice and coagulopathy reflecting the same functional consequences seen in other causes of liver failure.', 1),
('f6000000-0000-0000-0000-000000000006', 'This represents a serious, often pre-terminal complication of advanced metastatic cancer, and management focuses on supportive care and appropriate, sensitive discussion of goals of care given the generally poor prognosis.', 2),
('f6000000-0000-0000-0000-000000000006', 'Recognising this presentation in the context of known hepatic metastases avoids unnecessary further invasive investigation to search for an alternative, unlikely cause, while still appropriately considering and excluding other treatable causes where clinically relevant.', 3),
('f6000000-0000-0000-0000-000000000007', 'Even without current cord compression, a pathological fracture from bone metastases requires active multidisciplinary management to address pain, reduce further fracture risk, and treat the underlying metastatic disease.', 1),
('f6000000-0000-0000-0000-000000000007', 'Radiotherapy plays a role both in pain control and in potentially reducing further bone destruction/fracture risk at the affected site.', 2),
('f6000000-0000-0000-0000-000000000007', 'Ongoing vigilance for the development of cord compression is important, as this can evolve over time even if not present at initial assessment, requiring patient education about warning symptoms to report urgently.', 3),
('f6000000-0000-0000-0000-000000000008', 'Cancer significantly increases venous thromboembolism risk (cancer-associated thrombosis), reflecting a combination of tumour-related procoagulant factors, treatment effects, and reduced mobility.', 1),
('f6000000-0000-0000-0000-000000000008', 'Low molecular weight heparin has strong historical evidence specifically in cancer-associated thrombosis, though the role of DOACs in this population has expanded with more recent evidence, requiring individualised decision-making.', 2),
('f6000000-0000-0000-0000-000000000008', 'Ongoing anticoagulation duration in cancer-associated thrombosis is often longer or indefinite while active malignancy or treatment continues, reflecting the persistently elevated thrombotic risk in this population.', 3),
('f6000000-0000-0000-0000-000000000009', 'SIADH is a well-recognised paraneoplastic complication of small cell lung cancer, causing euvolaemic hyponatraemia with inappropriately concentrated urine.', 1),
('f6000000-0000-0000-0000-000000000009', 'Fluid restriction is the standard initial management for SIADH-related hyponatraemia, addressing the underlying mechanism (impaired free water excretion) directly.', 2),
('f6000000-0000-0000-0000-000000000009', 'Careful, gradual correction of severe hyponatraemia (regardless of treatment modality) is essential to avoid osmotic demyelination syndrome, a serious complication of overly rapid sodium correction.', 3),
('f6000000-0000-0000-0000-000000000010', 'Patient education about the low fever threshold (typically 38C) for seeking urgent assessment is a critical safety-netting measure given how rapidly neutropenic sepsis can progress.', 1),
('f6000000-0000-0000-0000-000000000010', 'Chemotherapy patients are typically given clear written and verbal information, including contact details for urgent assessment, as part of routine treatment counselling.', 2),
('f6000000-0000-0000-0000-000000000010', 'This proactive education aims to minimise delay in presentation, which is directly linked to outcomes in neutropenic sepsis.', 3),
('f6000000-0000-0000-0000-000000000011', 'Ovarian cancer commonly spreads via peritoneal carcinomatosis, which can cause malignant bowel obstruction through direct tumour infiltration, external compression, or disrupted bowel motility.', 1),
('f6000000-0000-0000-0000-000000000011', 'Dilated bowel loops with air-fluid levels on imaging confirm mechanical obstruction, though the malignant aetiology is inferred from the clinical context and typically confirmed with further cross-sectional imaging.', 2),
('f6000000-0000-0000-0000-000000000011', 'Management of malignant bowel obstruction requires individualised, often multidisciplinary decision-making, weighing the potential benefits and risks of surgical intervention against medical/palliative symptom management, depending on factors including extent of disease, prior treatment and patient preference.', 3),
('f6000000-0000-0000-0000-000000000012', 'An extremely elevated white cell count (often above 100x10^9/L in AML) creates hyperviscosity, impairing microvascular blood flow, particularly affecting the brain (confusion, visual disturbance) and lungs (breathlessness/hypoxia).', 1),
('f6000000-0000-0000-0000-000000000012', 'Hyperviscosity syndrome/leukostasis is a medical emergency requiring urgent cytoreductive treatment, as it carries a significant risk of intracranial haemorrhage and respiratory failure if untreated.', 2),
('f6000000-0000-0000-0000-000000000012', 'Leukapheresis (mechanically removing white cells) provides rapid cytoreduction while definitive chemotherapy is initiated, particularly useful in severe, symptomatic presentations like this one.', 3),
('f6000000-0000-0000-0000-000000000013', 'New severe headache, vomiting and reduced consciousness in a patient with known brain metastases and significant midline shift indicates dangerously raised intracranial pressure, a neuro-oncological emergency.', 1),
('f6000000-0000-0000-0000-000000000013', 'High-dose dexamethasone rapidly reduces peritumoural vasogenic oedema, often producing significant symptomatic improvement while further definitive treatment is planned.', 2),
('f6000000-0000-0000-0000-000000000013', 'Lumbar puncture is specifically contraindicated in this context due to the risk of precipitating brain herniation from the pressure gradient created by removing CSF below an intracranial mass lesion with significant midline shift.', 3),
('f6000000-0000-0000-0000-000000000014', 'PSA is organ-specific to the prostate but not cancer-specific, as it can also be raised in benign prostatic hyperplasia and prostatitis, requiring clinical correlation (examination findings, further investigation) rather than being diagnostic alone.', 1),
('f6000000-0000-0000-0000-000000000014', 'A hard, irregular prostate on digital rectal examination is a clinical finding that, combined with a raised PSA, significantly increases suspicion of malignancy over benign causes of PSA elevation.', 2),
('f6000000-0000-0000-0000-000000000014', 'PSA is also used for monitoring treatment response and detecting recurrence in patients already diagnosed with and treated for prostate cancer.', 3),
('f6000000-0000-0000-0000-000000000015', 'CA-125 is not specific to ovarian cancer and can be elevated in various benign conditions (endometriosis, fibroids, pelvic inflammatory disease) and other malignancies, so it must be interpreted alongside clinical and imaging findings.', 1),
('f6000000-0000-0000-0000-000000000015', 'A complex (rather than simple) ovarian mass on ultrasound, combined with markedly elevated CA-125, significantly increases the likelihood of malignancy, often quantified using a risk of malignancy index combining these features with menopausal status.', 2),
('f6000000-0000-0000-0000-000000000015', 'Non-specific symptoms (bloating, early satiety, pelvic/abdominal discomfort) are a recognised, though often overlooked, presentation of ovarian cancer, contributing to frequently delayed diagnosis if not appropriately investigated.', 3),
('f6000000-0000-0000-0000-000000000016', 'AFP and beta-hCG are characteristic tumour markers for germ cell tumours, with different histological subtypes producing different marker patterns (e.g. seminomas typically do not raise AFP, while non-seminomatous tumours often do).', 1),
('f6000000-0000-0000-0000-000000000016', 'A painless testicular mass in a young man should always raise suspicion of testicular cancer and prompt urgent ultrasound and tumour marker assessment.', 2),
('f6000000-0000-0000-0000-000000000016', 'These markers are valuable not only for diagnosis but for staging, monitoring response to treatment, and detecting relapse during follow-up.', 3),
('f6000000-0000-0000-0000-000000000017', 'Cirrhosis (from any cause) is a major risk factor for hepatocellular carcinoma, justifying regular structured surveillance in this population.', 1),
('f6000000-0000-0000-0000-000000000017', 'AFP is used alongside (not instead of) regular ultrasound imaging, as AFP sensitivity alone for detecting HCC is imperfect, making combined surveillance more effective.', 2),
('f6000000-0000-0000-0000-000000000017', 'A rising AFP trend, or a new/enlarging liver lesion on imaging, prompts further cross-sectional imaging (CT or MRI) to further characterise and confirm or exclude HCC.', 3),
('f6000000-0000-0000-0000-000000000018', 'CEA is not specific enough to be used for primary diagnosis or screening of colorectal cancer in an asymptomatic population but is valuable as a surveillance tool after diagnosis and treatment, where a rising trend from an established baseline is more meaningful.', 1),
('f6000000-0000-0000-0000-000000000018', 'A rising CEA during follow-up should prompt further investigation (imaging) to look for evidence of recurrent or metastatic disease, rather than being acted upon in isolation.', 2),
('f6000000-0000-0000-0000-000000000018', 'CEA can also be elevated by other conditions (e.g. smoking, inflammatory bowel disease, other cancers), which is important to consider when interpreting results, particularly any unexpected or isolated elevation.', 3),
('f6000000-0000-0000-0000-000000000019', 'Screening targets asymptomatic individuals within a defined risk population, aiming to shift diagnosis to an earlier, more treatable stage, distinguishing it from diagnostic pathways for symptomatic presentations.', 1),
('f6000000-0000-0000-0000-000000000019', 'Understanding both the benefits (mortality reduction) and limitations (false positives requiring further investigation, potential overdiagnosis of indolent disease) is part of informed participation in screening programmes.', 2),
('f6000000-0000-0000-0000-000000000019', 'Screening does not replace ongoing symptom awareness, as interval cancers (developing between screening rounds) can still occur and require prompt assessment if symptoms develop.', 3),
('f6000000-0000-0000-0000-000000000020', 'FIT specifically and sensitively detects human haemoglobin, distinguishing it from older guaiac-based faecal occult blood tests, which were less specific and could be affected by dietary factors.', 1),
('f6000000-0000-0000-0000-000000000020', 'A positive FIT result indicates possible occult bleeding requiring further investigation (typically colonoscopy) to identify the source, which may be colorectal cancer, polyps, or other causes of GI bleeding.', 2),
('f6000000-0000-0000-0000-000000000020', 'FIT screening aims to detect colorectal cancer and significant polyps at an earlier, more treatable stage in an asymptomatic population, similar in principle to other population-based cancer screening programmes.', 3),
('f6000000-0000-0000-0000-000000000021', 'A family history pattern of early-onset breast and/or ovarian cancer across multiple close relatives is a key indication for considering hereditary breast and ovarian cancer syndrome and BRCA1/BRCA2 testing.', 1),
('f6000000-0000-0000-0000-000000000021', 'BRCA1 and BRCA2 mutations significantly increase lifetime risk of breast and ovarian cancer (and, to a lesser extent, other cancers), informing decisions about enhanced surveillance, risk-reducing interventions, and family cascade testing.', 2),
('f6000000-0000-0000-0000-000000000021', 'Genetic counselling is an essential part of this process, helping patients understand the implications of testing (for themselves and family members) before and after results are available.', 3),
('f6000000-0000-0000-0000-000000000022', 'HPV primary screening programmes use HPV status to guide the screening pathway, with cytology used as a secondary test to help stratify risk in HPV-positive women.', 1),
('f6000000-0000-0000-0000-000000000022', 'Most HPV infections are transient and clear spontaneously within around a year, which is why earlier repeat testing (rather than immediate colposcopy) is appropriate when cytology is normal.', 2),
('f6000000-0000-0000-0000-000000000022', 'Persistent HPV positivity on repeat testing, or any abnormal cytology at the point of HPV positivity, would prompt referral for colposcopy for further assessment.', 3),
('f6000000-0000-0000-0000-000000000023', 'Tumour markers generally require a combination of adequate sensitivity, specificity and a detectable pre-clinical phase to be suitable for population screening, criteria that CA 19-9 does not sufficiently meet for pancreatic cancer.', 1),
('f6000000-0000-0000-0000-000000000023', $x$CA 19-9's clinical utility lies primarily in monitoring known, diagnosed pancreatic cancer (assessing treatment response, detecting recurrence), rather than in screening asymptomatic individuals.$x$, 2),
('f6000000-0000-0000-0000-000000000023', 'For individuals with a strong family history suggestive of a hereditary pancreatic cancer syndrome, referral for formal genetic counselling and consideration of established surveillance pathways (which may include specific imaging protocols) is more appropriate than relying on CA 19-9 testing alone.', 3),
('f6000000-0000-0000-0000-000000000024', 'Predictive biomarkers (distinct from prognostic markers) specifically help predict response to particular treatments, guiding personalised, targeted treatment selection in modern oncology practice.', 1),
('f6000000-0000-0000-0000-000000000024', $x$Certain molecular findings (e.g. MSI-high status) can also flag tumours suggestive of an underlying hereditary cancer syndrome (Lynch syndrome), prompting referral for genetic counselling and testing, which has implications for the patient's family as well.$x$, 2),
('f6000000-0000-0000-0000-000000000024', 'This reflects the increasing role of molecular/genomic tumour profiling in modern oncology, complementing traditional staging and histopathological assessment to guide truly personalised cancer treatment.', 3),
('f6000000-0000-0000-0000-000000000025', 'PSA trends over time (rather than a single value) are particularly informative in monitoring treatment response and detecting recurrence in patients with a known prostate cancer diagnosis.', 1),
('f6000000-0000-0000-0000-000000000025', 'A rising PSA (biochemical recurrence) may precede clinical or radiological evidence of disease progression, allowing for earlier consideration of further treatment strategies.', 2),
('f6000000-0000-0000-0000-000000000025', 'Further assessment following a rising PSA typically includes clinical evaluation and imaging to characterise the extent and location of any disease progression, guiding subsequent management decisions.', 3),
('f6000000-0000-0000-0000-000000000026', 'Low-dose CT specifically reduces radiation exposure compared with standard CT while retaining adequate sensitivity for detecting early lung nodules, making it suitable for repeated use in a screening context.', 1),
('f6000000-0000-0000-0000-000000000026', 'Screening is targeted at defined high-risk populations (based on age and smoking history/pack-years) rather than the general population, reflecting the balance of benefit versus harms (radiation exposure, false positives, overdiagnosis) in this specific higher-risk group.', 2),
('f6000000-0000-0000-0000-000000000026', 'Trial evidence has demonstrated a mortality benefit from low-dose CT screening in appropriately selected high-risk individuals, distinguishing it from chest X-ray, which did not show the same benefit in comparable trials.', 3),
('f6000000-0000-0000-0000-000000000027', 'Anthracycline cardiotoxicity is dose-dependent, with cumulative lifetime dose being a key risk factor, informing decisions about maximum cumulative dosing and the need for ongoing monitoring.', 1),
('f6000000-0000-0000-0000-000000000027', 'Cardiotoxicity can be either acute (during or shortly after treatment) or, more classically of concern, delayed/chronic (developing months to years later), justifying both during-treatment and longer-term surveillance in some protocols.', 2),
('f6000000-0000-0000-0000-000000000027', 'Baseline cardiac assessment before starting anthracycline treatment, with periodic monitoring during treatment, allows early detection of declining cardiac function, potentially prompting treatment modification.', 3),
('f6000000-0000-0000-0000-000000000028', $x$Cisplatin's nephrotoxicity relates to direct tubular cell damage, distinguishing its renal risk mechanism and management approach from other chemotherapy-related renal complications (e.g. tumour lysis syndrome).$x$, 1),
('f6000000-0000-0000-0000-000000000028', 'Adequate hydration before, during and after cisplatin administration is a standard, evidence-based measure to reduce nephrotoxicity risk by maintaining adequate renal blood flow and urine output.', 2),
('f6000000-0000-0000-0000-000000000028', 'Regular monitoring of renal function (and electrolytes, given cisplatin can also cause specific electrolyte wasting, e.g. magnesium) is an important part of safely administering this chemotherapy agent.', 3),
('f6000000-0000-0000-0000-000000000029', 'Cisplatin ototoxicity typically causes bilateral, high-frequency sensorineural hearing loss, often accompanied by tinnitus, related to direct cochlear hair cell damage.', 1),
('f6000000-0000-0000-0000-000000000029', 'This ototoxicity is often irreversible and dose-related (cumulative dose), making baseline and periodic audiometric assessment important for monitoring during treatment, particularly in patients receiving higher cumulative doses.', 2),
('f6000000-0000-0000-0000-000000000029', 'Awareness of this risk is important for patient counselling before starting treatment and for considering dose modification if significant hearing changes develop during treatment.', 3),
('f6000000-0000-0000-0000-000000000030', $x$Vincristine's neurotoxicity is dose-dependent and cumulative, affecting sensory, motor and autonomic nerve fibres, distinguishing its broad neuropathy pattern from some other chemotherapy-related neuropathies.$x$, 1),
('f6000000-0000-0000-0000-000000000030', 'Autonomic involvement, causing constipation (and sometimes more severe bowel motility problems), is a recognised feature of vincristine neurotoxicity alongside the more commonly recognised sensory symptoms.', 2),
('f6000000-0000-0000-0000-000000000030', 'Regular neurological assessment during vincristine treatment helps detect early neuropathy, guiding decisions about dose modification to balance efficacy against this cumulative, potentially significant toxicity.', 3),
('f6000000-0000-0000-0000-000000000031', 'Bleomycin pulmonary toxicity can develop during treatment or sometimes present later, and the lungs remain vulnerable to oxygen-related injury even after treatment has been completed.', 1),
('f6000000-0000-0000-0000-000000000031', 'This specific interaction (high-concentration oxygen precipitating or worsening bleomycin lung injury) is an important perioperative and anaesthetic consideration for any patient with a history of bleomycin exposure, regardless of how long ago treatment occurred.', 2),
('f6000000-0000-0000-0000-000000000031', 'Anaesthetists should be informed of any prior bleomycin exposure so that inspired oxygen concentration can be carefully managed (using the lowest concentration adequate for safe oxygenation) throughout any subsequent anaesthetic.', 3),
('f6000000-0000-0000-0000-000000000032', 'Methotrexate inhibits dihydrofolate reductase, blocking normal folate metabolism required for DNA synthesis in rapidly dividing cells, both tumour and normal.', 1),
('f6000000-0000-0000-0000-000000000032', 'Folinic acid provides a source of reduced folate that bypasses the blocked enzymatic step, allowing normal cells to continue functioning while relying on the differential methotrexate concentration/exposure to preserve relative anti-tumour selectivity.', 2),
('f6000000-0000-0000-0000-000000000032', 'Careful timing of folinic acid rescue (given after methotrexate, following a specific protocol schedule) is essential to balance protecting normal tissue from toxicity against not excessively compromising the anti-tumour effect.', 3),
('f6000000-0000-0000-0000-000000000033', '5-fluorouracil cardiotoxicity, though less common than anthracycline cardiotoxicity, is a recognised complication, classically presenting with chest pain and ischaemic ECG changes related to coronary vasospasm during or shortly after infusion.', 1),
('f6000000-0000-0000-0000-000000000033', 'Normal coronary arteries on angiography, despite ischaemic symptoms and ECG changes, support a vasospastic (rather than fixed atherosclerotic) mechanism.', 2),
('f6000000-0000-0000-0000-000000000033', 'Recognition of this toxicity is important as it may require stopping the infusion and reconsidering the chemotherapy regimen, given the risk of recurrent, potentially serious cardiac events with continued or repeated exposure.', 3),
('f6000000-0000-0000-0000-000000000034', 'Certain targeted therapies, including some tyrosine kinase inhibitors, have specific, recognised class side effects (such as hypertension) related to their mechanism of action on relevant signalling pathways, distinct from traditional cytotoxic chemotherapy side effects.', 1),
('f6000000-0000-0000-0000-000000000034', 'Regular monitoring protocols for targeted therapies are tailored to the specific, known side-effect profile of each individual drug class, reflecting the more targeted (and differently toxic) nature of these treatments compared with traditional chemotherapy.', 2),
('f6000000-0000-0000-0000-000000000034', 'Early detection and management of treatment-related hypertension helps reduce associated cardiovascular risk while allowing the patient to continue benefiting from effective cancer-directed therapy.', 3),
('f6000000-0000-0000-0000-000000000035', 'Combining antiemetics with different mechanisms of action (5-HT3 antagonist, dexamethasone, NK1 antagonist) provides more comprehensive coverage of the multiple pathways involved in chemotherapy-induced nausea and vomiting than relying on a single class.', 1),
('f6000000-0000-0000-0000-000000000035', 'NK1 receptor antagonists are particularly useful for highly emetogenic chemotherapy regimens and for controlling delayed-phase nausea and vomiting (occurring more than 24 hours after chemotherapy), which 5-HT3 antagonists alone control less effectively.', 2),
('f6000000-0000-0000-0000-000000000035', 'Appropriate antiemetic prophylaxis and escalation, tailored to the emetogenic potential of the specific chemotherapy regimen, is an important part of supportive cancer care, directly impacting patient quality of life and treatment tolerability.', 3),
('f6000000-0000-0000-0000-000000000036', 'Many chemotherapy agents (particularly alkylating agents) have gonadotoxic effects that can cause temporary or permanent infertility, making this an important consideration for patients of reproductive age.', 1),
('f6000000-0000-0000-0000-000000000036', 'Fertility preservation procedures generally require time to complete (e.g. ovarian stimulation for egg/embryo cryopreservation) and are most effective when performed before gonadotoxic treatment begins, making timely, proactive pre-treatment discussion essential.', 2),
('f6000000-0000-0000-0000-000000000036', 'This discussion should be part of routine, proactive pre-treatment counselling for both male and female patients of reproductive age, ideally with prompt referral to fertility specialists where fertility preservation is desired, to avoid delaying essential cancer treatment.', 3),
('f6000000-0000-0000-0000-000000000037', 'Chemotherapy targets rapidly dividing cells, which includes hair follicle cells, explaining why alopecia is a common toxicity across many regimens.', 1),
('f6000000-0000-0000-0000-000000000037', 'Reversibility of hair loss after treatment completion is an important, reassuring point for patient counselling, distinguishing it from some other, potentially permanent, chemotherapy toxicities.', 2),
('f6000000-0000-0000-0000-000000000037', 'Supportive measures such as scalp cooling can be offered for certain chemotherapy regimens to help reduce the severity of hair loss, reflecting the importance of addressing the psychological and quality-of-life impact of this visible side effect.', 3),
('f6000000-0000-0000-0000-000000000038', 'The nadir (lowest point of blood counts after chemotherapy) typically occurs around 7-14 days after treatment for many regimens, an important, predictable pattern for anticipating and monitoring this toxicity.', 1),
('f6000000-0000-0000-0000-000000000038', 'During the nadir period, patients are at increased risk of infection (from neutropenia), bleeding (from thrombocytopenia) and fatigue (from anaemia), guiding appropriate patient counselling and monitoring during this time.', 2),
('f6000000-0000-0000-0000-000000000038', 'Full blood count monitoring at appropriate intervals around each chemotherapy cycle allows tracking of the degree and recovery pattern of myelosuppression, informing decisions about dose timing and adjustment for subsequent cycles.', 3),
('f6000000-0000-0000-0000-000000000039', 'Small cell lung cancer is one of the most common causes of paraneoplastic SIADH, related to its neuroendocrine cell origin capable of ectopic hormone production.', 1),
('f6000000-0000-0000-0000-000000000039', 'Euvolaemic hyponatraemia with inappropriately concentrated urine (rather than the expected maximally dilute urine) is the biochemical hallmark of SIADH.', 2),
('f6000000-0000-0000-0000-000000000039', 'Identifying SIADH in a smoker should prompt urgent chest imaging to look for an underlying lung malignancy, given this strong, well-recognised association.', 3),
('f6000000-0000-0000-0000-000000000040', 'Post-tetanic potentiation of reflexes/power (improvement after sustained contraction) is a specific, distinguishing electrophysiological and clinical feature of Lambert-Eaton myasthenic syndrome.', 1),
('f6000000-0000-0000-0000-000000000040', 'Autonomic symptoms (dry mouth, constipation) commonly accompany LEMS, distinguishing it from myasthenia gravis.', 2),
('f6000000-0000-0000-0000-000000000040', 'The strong association with small cell lung cancer means a new LEMS diagnosis should prompt thorough investigation for an underlying malignancy if not already known.', 3),
('f6000000-0000-0000-0000-000000000041', $x$PTHrP shares structural homology with PTH at its receptor-binding region, allowing it to mimic PTH's calcium-raising effects on bone resorption and renal calcium reabsorption, despite being a distinct molecule.$x$, 1),
('f6000000-0000-0000-0000-000000000041', 'Squamous cell carcinomas (lung, head and neck, oesophagus, cervix) are classically associated with this humoral mechanism of hypercalcaemia, distinguishing it from hypercalcaemia caused by direct bone metastasis or other mechanisms.', 2),
('f6000000-0000-0000-0000-000000000041', 'PTH is appropriately suppressed in this scenario due to negative feedback from the PTHrP-driven hypercalcaemia, a key biochemical distinguishing feature from primary hyperparathyroidism.', 3),
('f6000000-0000-0000-0000-000000000042', 'Ovarian teratoma is a classic, well-recognised association with anti-NMDA receptor encephalitis, thought to relate to ectopic neural tissue within the tumour triggering an immune response that cross-reacts with NMDA receptors in the brain.', 1),
('f6000000-0000-0000-0000-000000000042', 'The characteristic evolving symptom pattern -- psychiatric symptoms, seizures, movement abnormalities (often orofacial dyskinesias), and autonomic instability -- is a recognised clinical progression in this condition.', 2),
('f6000000-0000-0000-0000-000000000042', 'Identifying and treating (or removing) the underlying tumour, alongside immunotherapy, is an important part of managing this paraneoplastic autoimmune encephalitis.', 3),
('f6000000-0000-0000-0000-000000000043', 'Anti-Yo antibodies are strongly associated with paraneoplastic cerebellar degeneration, particularly in the context of breast or gynaecological (ovarian) malignancy.', 1),
('f6000000-0000-0000-0000-000000000043', 'A normal MRI, despite significant clinical cerebellar dysfunction, is a characteristic and important feature of paraneoplastic cerebellar degeneration, reflecting a primarily antibody/immune-mediated process rather than a structural lesion.', 2),
('f6000000-0000-0000-0000-000000000043', 'Symptoms often progress relatively rapidly over weeks and can precede the diagnosis of the underlying malignancy, making recognition of this pattern important for prompting a search for an occult tumour.', 3),
('f6000000-0000-0000-0000-000000000044', 'The malignancy association is strongest around the time of dermatomyositis diagnosis, particularly within the first one to two years, justifying screening at this stage.', 1),
('f6000000-0000-0000-0000-000000000044', 'The association is notably stronger in dermatomyositis than in polymyositis, an important distinguishing feature between these related inflammatory myopathies when considering screening intensity.', 2),
('f6000000-0000-0000-0000-000000000044', 'This paraneoplastic-type association means dermatomyositis can sometimes be the presenting feature that leads to diagnosis of an underlying, previously unrecognised malignancy.', 3),
('f6000000-0000-0000-0000-000000000045', 'Paraneoplastic peripheral neuropathy is one of several recognised remote effects of malignancy on the nervous system, occurring without direct tumour invasion or metastasis to the affected nerves.', 1),
('f6000000-0000-0000-0000-000000000045', 'A thorough workup excluding other common causes of peripheral neuropathy (diabetes, vitamin deficiencies, chemotherapy-related toxicity, alcohol) is important, as paraneoplastic neuropathy is often a diagnosis of exclusion alongside supportive antibody testing where relevant.', 2),
('f6000000-0000-0000-0000-000000000045', 'Recognising a paraneoplastic neurological syndrome can sometimes prompt earlier diagnosis of an underlying malignancy, or inform prognosis and management discussions in a patient with a known cancer diagnosis.', 3),
('f6000000-0000-0000-0000-000000000046', 'Renal cell carcinoma is one of several tumours (alongside hepatocellular carcinoma and some cerebellar haemangioblastomas) recognised to cause paraneoplastic erythrocytosis through ectopic erythropoietin production.', 1),
('f6000000-0000-0000-0000-000000000046', 'Distinguishing this paraneoplastic mechanism from primary polycythaemia vera (typically JAK2-positive, with additional features such as pruritus and thrombosis risk) is important, as the underlying mechanism and associated risks differ.', 2),
('f6000000-0000-0000-0000-000000000046', 'Recognising paraneoplastic erythrocytosis can occasionally be a clue prompting investigation for an underlying renal or other tumour in a patient presenting with unexplained polycythaemia.', 3),
('f6000000-0000-0000-0000-000000000047', 'Rapid onset of acanthosis nigricans in an older, non-obese patient (rather than the more gradual, insulin-resistance-related form typically seen in younger, obese patients) should raise suspicion for an underlying malignancy.', 1),
('f6000000-0000-0000-0000-000000000047', 'Gastric adenocarcinoma is the classic malignancy associated with malignant acanthosis nigricans, though other GI and non-GI cancers can also be associated.', 2),
('f6000000-0000-0000-0000-000000000047', 'Recognising this cutaneous sign can prompt investigation for an underlying malignancy if not already diagnosed, or support the paraneoplastic nature of the finding in a patient with a known cancer diagnosis.', 3),
('f6000000-0000-0000-0000-000000000048', 'Cancer-associated retinopathy is a rare but recognised paraneoplastic syndrome, most classically associated with small cell lung cancer, resulting from antibodies that cross-react with retinal antigens (e.g. recoverin).', 1),
('f6000000-0000-0000-0000-000000000048', 'Photosensitivity and rapidly progressive visual loss, with specific retinal examination findings and confirmatory antibody testing, help distinguish this paraneoplastic process from more common causes of visual impairment.', 2),
('f6000000-0000-0000-0000-000000000048', 'Recognition of this rare syndrome can occasionally prompt investigation for an underlying malignancy if not previously diagnosed, though it is rare enough that common causes of visual loss should still be considered and excluded first in most contexts.', 3),
('f6000000-0000-0000-0000-000000000049', $x$Small cell lung cancer's neuroendocrine origin explains its capacity for ectopic hormone production, including ACTH, causing paraneoplastic Cushing's syndrome.$x$, 1),
('f6000000-0000-0000-0000-000000000049', $x$Ectopic ACTH syndrome often has a more rapid onset and more severe biochemical disturbance (including pronounced hypokalaemia) compared with pituitary-dependent Cushing's disease, reflecting the typically higher, less regulated ACTH levels produced by the tumour.$x$, 2),
('f6000000-0000-0000-0000-000000000049', $x$A raised ACTH confirms an ACTH-dependent cause, with further tests (e.g. high-dose dexamethasone suppression testing, imaging) used to help distinguish ectopic ACTH secretion from pituitary-dependent Cushing's disease when the underlying tumour is not already known.$x$, 3),
('f6000000-0000-0000-0000-000000000050', 'The combination of digital clubbing with painful periosteal new bone formation (visible on X-ray, particularly affecting the long bones) is the defining feature of hypertrophic pulmonary osteoarthropathy.', 1),
('f6000000-0000-0000-0000-000000000050', 'Although classically associated with lung cancer, HPOA can occur with various other malignancies and some benign conditions, making recognition of this specific syndrome pattern clinically useful regardless of the exact underlying cause.', 2),
('f6000000-0000-0000-0000-000000000050', 'Symptoms of HPOA can sometimes precede the diagnosis of the underlying malignancy, making it an important clinical sign prompting further investigation when identified.', 3);
